// FICHIER GÉNÉRÉ par scripts/build-agent.mjs : ne pas modifier à la main.
export const AGENT_FILES = {
 "hub_client.py": "\"\"\"Client du hub (Cloudflare Worker) : sondage des commandes + envoi d'état. Bibliothèque standard seulement.\"\"\"\nimport json\nimport os\nimport threading\nimport time\nimport urllib.error\nimport urllib.request\n\nHERE = os.path.dirname(os.path.abspath(__file__))\n\n\ndef load_config(path=None):\n    path = path or os.path.join(HERE, \"hub.json\")\n    with open(path, encoding=\"utf8\") as f:\n        cfg = json.load(f)\n    cfg[\"url\"] = cfg[\"url\"].rstrip(\"/\")\n    return cfg\n\n\nclass Hub:\n    \"\"\"Une instance par bot. Thread-safe : on peut appeler report() depuis plusieurs threads.\"\"\"\n\n    def __init__(self, bot, name, cfg=None, log=print):\n        self.cfg = cfg or load_config()\n        self.bot = bot\n        self.name = name\n        self.log = log\n        self._lock = threading.Lock()\n        self._pending = {\"messages\": [], \"events\": [], \"results\": []}\n        self._fails = 0\n        self.online = False\n\n    # ------------------------------------------------------------------ HTTP\n    def _req(self, method, path, body=None, timeout=30):\n        data = json.dumps(body).encode() if body is not None else None\n        req = urllib.request.Request(\n            self.cfg[\"url\"] + path, data=data, method=method,\n            headers={\"Authorization\": \"Bearer \" + self.cfg[\"key\"], \"Content-Type\": \"application/json\",\n                     \"User-Agent\": \"bot-hub-agent/1\"},\n        )\n        with urllib.request.urlopen(req, timeout=timeout) as r:\n            return json.loads(r.read().decode(\"utf8\") or \"{}\")\n\n    # ------------------------------------------------------------------ API\n    def poll(self, wait=20):\n        \"\"\"Retourne la liste des commandes à exécuter ([] si rien). Ne lève jamais.\"\"\"\n        try:\n            out = self._req(\"GET\", f\"/api/agent/poll?bot={self.bot}&wait={int(wait)}\", timeout=wait + 15)\n            self._ok()\n            return out.get(\"commands\", [])\n        except urllib.error.HTTPError as e:\n            self._fail(f\"HTTP {e.code}\")\n            if e.code in (401, 503):\n                self.log(\"Le hub refuse la clé de l'agent (AGENT_KEY) : relance l'installation de l'agent.\")\n        except Exception as e:  # réseau coupé, Worker en maintenance...\n            self._fail(f\"{type(e).__name__}\")\n        time.sleep(min(60, 3 * self._fails))\n        return []\n\n    def message(self, text, html=False, markup=None):\n        with self._lock:\n            self._pending[\"messages\"].append({\"text\": text, \"html\": html, **({\"markup\": markup} if markup else {})})\n\n    def event(self, text, level=\"info\"):\n        with self._lock:\n            self._pending[\"events\"].append({\"level\": level, \"text\": text})\n\n    def result(self, cmd_id, ok, text=\"\", html=False, markup=None):\n        with self._lock:\n            self._pending[\"results\"].append({\"id\": cmd_id, \"ok\": ok, \"text\": text, \"html\": html, **({\"markup\": markup} if markup else {})})\n\n    def flush(self, state=None):\n        \"\"\"Envoie l'état + tout ce qui est en attente. Si le hub est injoignable, on garde pour la prochaine fois.\"\"\"\n        with self._lock:\n            batch = {k: v[:] for k, v in self._pending.items()}\n            for k in self._pending:\n                self._pending[k] = []\n        body = {\"bot\": self.bot, \"name\": self.name, **batch}\n        if state is not None:\n            body[\"state\"] = state\n        try:\n            self._req(\"POST\", \"/api/agent/report\", body)\n            self._ok()\n            return True\n        except Exception as e:\n            self._fail(f\"{type(e).__name__}\")\n            with self._lock:  # on remet en file (borné)\n                for k, v in batch.items():\n                    self._pending[k] = (v + self._pending[k])[-100:]\n            return False\n\n    # ------------------------------------------------------------------ suivi de connexion\n    def _ok(self):\n        if not self.online:\n            self.log(\"Hub joignable.\")\n        self.online, self._fails = True, 0\n\n    def _fail(self, why):\n        self._fails += 1\n        if self.online or self._fails == 1:\n            self.log(f\"Hub injoignable ({why}), nouvel essai bientôt.\")\n        self.online = False\n",
 "tgtg_hub.py": "#!/usr/bin/env python3\n\"\"\"\nBot Too Good To Go branché sur le hub. Remplace tgtg_monitor.py (mêmes jetons, mêmes fonctions) :\nplus de polling Telegram ici, le hub reçoit les commandes et les relaie. Tout se pilote aussi depuis l'interface web.\n\"\"\"\nimport base64\nimport collections\nimport json\nimport os\nimport re\nimport sys\nimport threading\nimport time\nfrom datetime import datetime\nfrom zoneinfo import ZoneInfo\n\nfrom hub_client import Hub, HERE, load_config\n\nPARIS = ZoneInfo(\"Europe/Paris\")\nTOKEN_FILE = os.path.join(HERE, \"tgtg_tokens.json\")\n\nUA_FILE = os.path.join(HERE, \"tgtg_ua.txt\")\nDEFAULT_UA = \"TGTG/26.7.2 Dalvik/2.1.0 (Linux; U; Android 14; Pixel 8 Pro Build/UP1A.231005.007)\"\n\n\ndef stable_user_agent():\n    \"\"\"UA de l'app TGTG récent et fixe. Surcharge : variable TGTG_USER_AGENT ou fichier tgtg_ua.txt.\"\"\"\n    env = os.environ.get(\"TGTG_USER_AGENT\", \"\").strip()\n    if env:\n        return env\n    try:\n        with open(UA_FILE, encoding=\"utf8\") as f:\n            v = f.read().strip()\n            if v:\n                return v\n    except OSError:\n        pass\n    return DEFAULT_UA\n\nCONFIG_FILE = os.path.join(HERE, \"tgtg_hub_config.json\")\nMIN_INTERVAL = 15\nSTATE_EVERY = 20  # s\n\n\nBACKOFF = (5, 5, 30, 60, 120, 300, 600)  # secondes d'attente après le 1er, 2e, 3e… échec 403 d'affilée\n\n\ndef token_valid_for(access_token, minutes=30):\n    \"\"\"Vrai si le jeton d'accès (JWT) reste valable au moins `minutes` : inutile de le renouveler au démarrage.\"\"\"\n    try:\n        part = str(access_token).split(\".\")[1]\n        exp = json.loads(base64.urlsafe_b64decode(part + \"=\" * (-len(part) % 4)))[\"exp\"]\n        return exp - time.time() > minutes * 60\n    except Exception:\n        return False\n\n\ndef now_paris():\n    return datetime.now(PARIS)\n\n\ndef esc(s):\n    return str(s).replace(\"&\", \"&amp;\").replace(\"<\", \"&lt;\").replace(\">\", \"&gt;\")\n\n\nclass Bot:\n    def __init__(self, hub, cfg, client_factory):\n        self.hub, self.cfg, self.client_factory = hub, cfg, client_factory\n        self.client = None\n        self.started = time.time()\n        self.lock = threading.RLock()\n        self.logbuf = collections.deque(maxlen=200)\n        self.settings = self.load_settings()\n        self.items = {}            # item_id -> dict(name, qty, price, store)\n        self.prev = {}             # item_id -> qty\n        self.first_scan = True\n        self.last_scan = 0.0\n        self.last_ok = time.time()\n        self.fail_count = 0\n        self.down_alerted = False\n        self.proxy_index = 1  # toujours via les proxys Webshare tournants (comme l'ancien script), jamais l'IP du serveur\n        self.cookies = {}        # n° de proxy -> cookie DataDome qui a FONCTIONNÉ avec ce proxy (il est lié à son IP)\n        self.saved_cookie = None  # cookie d'origine du fichier de jetons, essayé une fois sur chaque proxy\n        self.tried_saved = set()\n        self.orders = []\n        self.force_refresh = False\n        self.last_refresh_try = 0.0\n        self.ok_count, self.last_beat = 0, time.time()  # bilan périodique des scans réussis dans le journal\n        self.stop = False\n        self.scan_lock = threading.Lock()  # « Scanner maintenant » et la boucle de scan ne doivent jamais appeler TGTG en même temps\n        self.reboot = False\n\n    # ------------------------------------------------------------------ journal\n    def log(self, msg, lvl=\"info\"):\n        line = f\"{now_paris():%H:%M:%S} {msg}\"\n        self.logbuf.append(line)\n        print(line, flush=True)\n        if lvl in (\"warn\", \"bad\", \"ok\"):\n            self.hub.event(msg, lvl)\n\n    # ------------------------------------------------------------------ réglages\n    def load_settings(self):\n        s = {\"enabled\": True, \"hour_start\": 6, \"hour_end\": 12, \"interval\": 15, \"auto_reserve\": True, \"auto_quantity\": 1, \"done_date\": \"\"}\n        # reprise des réglages de l'ancien script s'ils existent\n        old = os.path.join(HERE, \"tgtg_config.json\")\n        for path in (old, CONFIG_FILE):\n            try:\n                with open(path, encoding=\"utf8\") as f:\n                    raw = json.load(f)\n            except Exception:\n                continue\n            alias = {\"hour_start\": (\"hour_start\", \"HOUR_START\", \"start\", \"heure_debut\"),\n                     \"hour_end\": (\"hour_end\", \"HOUR_END\", \"end\", \"heure_fin\"),\n                     \"interval\": (\"interval\", \"scan_interval\", \"SCAN_INTERVAL\"),\n                     \"auto_reserve\": (\"auto_reserve\", \"auto\", \"AUTO_RESERVE\"),\n                     \"auto_quantity\": (\"auto_quantity\", \"auto_qty\", \"AUTO_QUANTITY\", \"quantity\"),\n                     \"enabled\": (\"enabled\",), \"done_date\": (\"done_date\",)}\n            for k, names in alias.items():\n                for n in names:\n                    if n in raw:\n                        s[k] = raw[n]\n                        break\n        s[\"hour_start\"] = int(s[\"hour_start\"]) % 24\n        he = int(s[\"hour_end\"])\n        s[\"hour_end\"] = 24 if he % 24 == 0 else he % 24\n        s[\"interval\"] = max(MIN_INTERVAL, int(s[\"interval\"]))\n        s[\"enabled\"] = bool(s[\"enabled\"])\n        s[\"done_date\"] = str(s[\"done_date\"] or \"\")\n        s[\"auto_reserve\"] = bool(s[\"auto_reserve\"])\n        s[\"auto_quantity\"] = min(3, max(1, int(s[\"auto_quantity\"])))\n        return s\n\n    def save_settings(self):\n        with open(CONFIG_FILE, \"w\", encoding=\"utf8\") as f:\n            json.dump(self.settings, f, indent=2)\n\n    def done_today(self):\n        return self.settings.get(\"done_date\") == f\"{now_paris():%Y-%m-%d}\"\n\n    def in_hours(self):\n        if not self.settings.get(\"enabled\", True):  # bouton « Arrêter » : aucun scan, quelle que soit l'heure\n            return False\n        if self.done_today():  # « fini pour aujourd'hui » : reprise automatique le lendemain\n            return False\n        h, a, b = now_paris().hour, self.settings[\"hour_start\"], self.settings[\"hour_end\"]\n        return a <= h < b if a < b else (h >= a or h < b)\n\n    # ------------------------------------------------------------------ client TGTG\n    def proxies(self):\n        p = self.cfg.get(\"tgtg\", {}).get(\"proxy\")\n        if not p:\n            return None\n        user = f\"{p['user_base']}{self.proxy_index}\"\n        url = f\"http://{user}:{p['password']}@{p['host']}:{p.get('port', 80)}\"\n        return {\"http\": url, \"https\": url}\n\n    def connect(self):\n        try:\n            with open(TOKEN_FILE, encoding=\"utf8\") as f:\n                t = json.load(f)\n        except Exception as e:\n            raise SystemExit(f\"Jetons TGTG introuvables ({TOKEN_FILE}) : {e}\")\n        self.cookies = {str(k): v for k, v in (t.get(\"datadome_by_proxy\") or {}).items() if v}\n        self.saved_cookie = t.get(\"datadome_cookie\") or None\n        count = int((self.cfg.get(\"tgtg\", {}).get(\"proxy\") or {}).get(\"count\", 1) or 1)\n        try:\n            self.proxy_index = min(max(1, int(t.get(\"proxy_index\") or 1)), count)  # on repart du dernier proxy qui marchait\n        except (TypeError, ValueError):\n            self.proxy_index = 1\n        self.tried_saved.add(self.proxy_index)\n        self.client = self.client_factory(\n            access_token=t.get(\"access_token\", \"\"), refresh_token=t.get(\"refresh_token\", \"\"),\n            datadome_cookie=self.cookies.get(str(self.proxy_index)) or self.saved_cookie, proxies=self.proxies())\n        self.tokens_snapshot = json.dumps(t, sort_keys=True)\n\n    def save_tokens(self):\n        c = self.client\n        cur = {\"access_token\": getattr(c, \"access_token\", None), \"refresh_token\": getattr(c, \"refresh_token\", None)}\n        if not cur[\"access_token\"] or not cur[\"refresh_token\"]:\n            return\n        try:\n            with open(TOKEN_FILE, encoding=\"utf8\") as f:\n                old = json.load(f)\n        except Exception:\n            old = {}\n        new = {**old, **{k: v for k, v in cur.items() if v}}\n        new[\"proxy_index\"] = self.proxy_index\n        if self.cookies:\n            new[\"datadome_by_proxy\"] = dict(self.cookies)\n        if json.dumps(new, sort_keys=True) != json.dumps(old, sort_keys=True):\n            tmp = TOKEN_FILE + \".tmp\"\n            with open(tmp, \"w\", encoding=\"utf8\") as f:\n                json.dump(new, f, indent=2)\n            os.replace(tmp, TOKEN_FILE)\n            self.log(\"Jetons TGTG renouvelés et sauvegardés.\")\n\n    def fresh_cookie(self):\n        \"\"\"Cookie DataDome neuf, demandé via le proxy en cours (le cookie est lié à l'IP qui le demande).\"\"\"\n        c, mod = self.client, getattr(self, \"tgtg_mod\", None)\n        c.cookie = \"datadome=init\"\n        if mod is None or not hasattr(c, \"_fetch_datadome_cookie\"):\n            return\n        orig = mod.requests.post\n        mod.requests.post = lambda *a, **k: orig(*a, **({\"proxies\": c.proxies, **k} if c.proxies else k))\n        try:\n            c._fetch_datadome_cookie(\"https://apptoogoodtogo.com/api/\")\n        finally:\n            mod.requests.post = orig\n        fresh = [x.value for x in c.session.cookies if x.name == \"datadome\" and x.value]\n        if fresh:\n            c.cookie = f\"datadome={fresh[-1]}\"\n\n    def refresh_if_due(self):\n        \"\"\"Renouvellement du jeton (toutes les 4 h) : l'appel le plus surveillé par DataDome. Il passe en direct depuis le\n        serveur ; on remet ensuite proxy ET cookie d'avant (le cookie reçu en direct est lié à l'IP du serveur).\"\"\"\n        c = self.client\n        if not hasattr(c, \"_refresh_token\"):\n            return\n        # Échéance réelle du jeton (JWT, 48 h chez TGTG) au lieu des 4 h supposées par la lib ; renouvellement si < 6 h\n        # restantes ou après un 401. Jamais plus d'une tentative toutes les 10 min (pas de martèlement si ça échoue).\n        if not self.force_refresh and token_valid_for(c.access_token, 360):\n            return\n        if time.time() - self.last_refresh_try < 600:\n            return\n        self.last_refresh_try, self.force_refresh = time.time(), False\n        keep_px, keep_ck = c.proxies, c.cookie\n        try:\n            c.proxies, c.last_time_token_refreshed = None, None\n            c._refresh_token()\n        except Exception:\n            c.proxies, c.cookie, c.last_time_token_refreshed = keep_px, keep_ck, None\n            c._refresh_token()  # dernier recours : via le proxy\n        finally:\n            c.proxies, c.cookie = keep_px, keep_ck\n        self.log(\"Jeton TGTG renouvelé\")\n        self.save_tokens()  # tout de suite : sinon, si le scan qui suit échoue, les nouveaux jetons sont perdus au redémarrage\n\n    def rotate_proxy(self):\n        p = self.cfg.get(\"tgtg\", {}).get(\"proxy\")\n        if not p:\n            return\n        self.proxy_index = (self.proxy_index % int(p.get(\"count\", 1))) + 1\n        try:\n            self.client.proxies = self.proxies()\n            self.client.session.cookies.clear()  # nouvelle IP : cookie connu pour ce proxy, sinon l'original (1 essai), sinon neuf\n            key = str(self.proxy_index)\n            if self.cookies.get(key):\n                self.client.cookie = self.cookies[key]\n            elif self.saved_cookie and self.proxy_index not in self.tried_saved:\n                self.tried_saved.add(self.proxy_index)\n                self.client.cookie = self.saved_cookie if \"=\" in self.saved_cookie else \"datadome=\" + self.saved_cookie\n            else:\n                self.fresh_cookie()\n        except Exception:\n            pass\n        self.log(f\"Rotation du proxy -> {p['user_base']}{self.proxy_index}\", \"warn\")\n\n    # ------------------------------------------------------------------ extraction d'un favori\n    @staticmethod\n    def parse_item(it):\n        item = it.get(\"item\", {})\n        price = item.get(\"price_including_taxes\", {}) or {}\n        eur = price.get(\"minor_units\", 0) / (10 ** price.get(\"decimals\", 2))\n        addr = ((it.get(\"store\", {}) or {}).get(\"store_location\", {}) or {}).get(\"address\", {}) or {}\n        slot = it.get(\"pickup_interval\") or {}\n        pick = \"\"\n        if slot.get(\"start\"):\n            pick = f\"{slot['start'][11:16]}-{(slot.get('end') or '')[11:16]}\"\n        return {\n            \"id\": str(item.get(\"item_id\", \"?\")), \"name\": it.get(\"display_name\", \"Inconnu\"),\n            \"qty\": int(it.get(\"items_available\", 0) or 0), \"price\": eur,\n            \"address\": addr.get(\"address_line\", \"\"), \"pickup\": pick,\n            \"slot_start\": (slot.get(\"start\") or \"\")[:16].replace(\"T\", \" \"),\n            \"slot_end\": (slot.get(\"end\") or \"\")[:16].replace(\"T\", \" \"),\n        }\n\n    # ------------------------------------------------------------------ scan\n    def scan_once(self):\n        with self.scan_lock:\n            self._scan_once()\n\n    def _scan_once(self):\n        self.refresh_if_due()\n        raw = self.client.get_items(favorites_only=True)\n        found = {}\n        for it in raw:\n            p = self.parse_item(it)\n            found[p[\"id\"]] = p\n        with self.lock:\n            self.items = found\n        self.last_scan = time.time()\n        self.last_ok = self.last_scan\n        ck = getattr(self.client, \"cookie\", None)\n        if isinstance(ck, str) and ck.startswith(\"datadome=\") and \"datadome=init\" not in ck:\n            self.cookies[str(self.proxy_index)] = ck  # cette paire proxy + cookie fonctionne : on la mémorise\n        if self.fail_count >= 3 or self.down_alerted:\n            self.hub.message(\"✅ TGTG : les scans fonctionnent de nouveau.\")\n            self.log(\"Scans de nouveau OK\", \"ok\")\n        self.fail_count, self.down_alerted = 0, False\n        self.ok_count += 1\n        if time.time() - self.last_beat >= 300:\n            self.log(f\"{self.ok_count} scan(s) OK en {int(time.time() - self.last_beat) // 60} min (proxy {self.proxy_index})\")\n            self.ok_count, self.last_beat = 0, time.time()\n        if self.first_scan:\n            self.prev = {k: v[\"qty\"] for k, v in found.items()}\n            self.first_scan = False\n            self.log(f\"{len(found)} favori(s) suivis\")\n            return\n        for k, p in found.items():\n            before = self.prev.get(k, 0)\n            if before == 0 and p[\"qty\"] >= 1:\n                self.on_available(p)\n            self.prev[k] = p[\"qty\"]\n\n    def on_available(self, p):\n        self.log(f\"DISPO : {p['name']} x{p['qty']} à {p['price']:.2f}€\", \"ok\")\n        qty = min(self.settings[\"auto_quantity\"], p[\"qty\"])\n        reserved = None\n        if self.settings[\"auto_reserve\"]:\n            reserved = self.reserve(p[\"id\"], qty, auto=True)\n        n = max(1, min(3, p[\"qty\"]))\n        row = [{\"text\": f\"🛒 {i} panier{'s' if i > 1 else ''}\", \"callback_data\": f\"c:tgtg:reserve:{p['id']}:{i}\"} for i in range(1, n + 1)]\n        pick = f\"\\n⏰ <b>Retrait :</b> {esc(p['slot_start'])} → {esc(p['slot_end'])}\" if p[\"slot_start\"] else \"\"\n        text = (f\"🛍️ <b>{esc(p['name'])}</b>\\n✅ {p['qty']} panier(s) disponible(s)\\n💶 <b>{p['price']:.2f} €</b>\\n📍 {esc(p['address'])}{pick}\"\n                + (f\"\\n\\n{reserved}\" if reserved else \"\"))\n        self.hub.message(text, html=True, markup={\"inline_keyboard\": [row]})\n        self.hub.flush(self.state())  # une alerte ne doit pas attendre le prochain envoi périodique\n\n    def reserve(self, item_id, qty, auto=False):\n        try:\n            order = self.client.create_order(item_id, qty)\n            oid = order.get(\"id\", \"?\")\n            self.log(f\"Réservation {'auto ' if auto else ''}OK : {oid}\", \"ok\")\n            return (f\"✅ <b>{'Réservé automatiquement' if auto else 'Réservé'} !</b> ({qty} panier(s))\\nCommande : <code>{esc(oid)}</code>\\n\"\n                    f\"⚠️ Paye dans l'app TGTG dans les minutes qui viennent.\\nPour annuler : /annuler {esc(oid)}\")\n        except Exception as e:\n            self.log(f\"Réservation impossible : {e}\", \"bad\")\n            return f\"❌ Réservation impossible : {esc(e)}\"\n\n    def scan_loop(self):\n        while not self.stop:\n            try:\n                if not self.in_hours():\n                    self.last_ok = time.time()  # hors plage : le compteur « sans succès depuis 10 min » repart de zéro à l'ouverture\n                    self.down_alerted = False\n                    time.sleep(30)\n                    continue\n                self.scan_once()\n                self.save_tokens()\n            except Exception as e:\n                self.fail_count += 1\n                self.log(f\"Scan en erreur ({self.fail_count}) : {str(e)[:150]}\", \"warn\")\n                blocked = \"403\" in str(e)\n                if \"401\" in str(e)[:6]:\n                    # jeton refusé : un changement de proxy n'y peut rien, on force un renouvellement au prochain scan\n                    self.force_refresh = True\n                elif self.fail_count >= 10 and self.fail_count % 5 == 0:  # on reste sur le proxy + cookie qui marchent ; changement seulement après un long échec\n                    self.rotate_proxy()\n                if time.time() - self.last_ok > 600 and not self.down_alerted:\n                    self.down_alerted = True\n                    self.hub.message(f\"🔴 TGTG : plus aucun scan réussi depuis 10 min ({str(e)[:100]}). Jeton mort, proxy HS ou blocage ?\")\n                    self.log(\"Plus de scan réussi depuis 10 min\", \"bad\")\n                # blocage DataDome : on ralentit de plus en plus (le blocage dépend du rythme des requêtes et est\n                # temporaire ; marteler toutes les 4 s sur tous les proxys l'entretient)\n                time.sleep(BACKOFF[min(self.fail_count - 1, len(BACKOFF) - 1)] if blocked else 15)\n                continue\n            time.sleep(self.settings[\"interval\"])\n\n    # ------------------------------------------------------------------ commandes\n    def fav_text(self):\n        with self.lock:\n            items = list(self.items.values())\n        if not items:\n            return \"Aucun favori lu pour le moment (scan hors plage horaire ou en attente).\"\n        lines = [\"📋 <b>Tes favoris</b>\\n\"]\n        for p in sorted(items, key=lambda x: -x[\"qty\"]):\n            lines.append(f\"{'🟢' if p['qty'] else '🔴'} <b>{esc(p['name'])}</b> — {p['qty']} dispo · {p['price']:.2f} €\")\n        return \"\\n\".join(lines)\n\n    def fetch_orders(self):\n        c = self.client\n        if hasattr(c, \"get_active\"):\n            r = c.get_active()\n            orders = r.get(\"orders\", []) if isinstance(r, dict) else (r or [])\n        else:\n            orders = c._post(\"order/v8/active\").json().get(\"orders\", [])\n        self.orders = orders\n        return orders\n\n    def orders_text(self):\n        orders = self.fetch_orders()\n        if not orders:\n            return \"📭 Aucune commande active.\"\n        lines = [\"📦 <b>Commandes actives</b>\\n\"]\n        for o in orders:\n            name = (o.get(\"item\", {}) or {}).get(\"name\") or o.get(\"item_name\") or \"?\"\n            lines.append(f\"• <b>{esc(name)}</b> — {esc(o.get('state', '?'))}\\n  <code>{esc(o.get('id', '?'))}</code>\")\n        return \"\\n\".join(lines)\n\n    def refresh_orders_quietly(self):\n        \"\"\"Relit les commandes actives pour que le tableau de la page web soit à jour (sans jamais faire échouer l'action).\"\"\"\n        try:\n            self.fetch_orders()\n        except Exception as e:\n            self.log(f\"Lecture des commandes impossible : {str(e)[:120]}\")\n\n    @staticmethod\n    def words(args):\n        t = str(args.get(\"text\", \"\") or \"\").strip()\n        return [w for w in re.split(r\"[\\s:]+\", t) if w]\n\n    def handle(self, c):\n        cmd, args = c[\"cmd\"], c.get(\"args\") or {}\n        w = self.words(args)\n        s = self.settings\n        if cmd in (\"favoris\", \"scan\"):\n            if cmd == \"scan\":\n                self.scan_once()\n                with self.lock:\n                    n, avail = len(self.items), sum(1 for p in self.items.values() if p[\"qty\"] > 0)\n                return True, f\"🔄 Scan fait : {n} favori(s), {avail} disponible(s).\\n\\n\" + self.fav_text(), True\n            return True, self.fav_text(), True\n        if cmd == \"commandes\":\n            return True, self.orders_text(), True\n        if cmd == \"annuler\":\n            oid = args.get(\"order\") or (w[0] if w else \"\")\n            if not oid:\n                return False, \"Usage : /annuler <numéro de commande>\", False\n            self.client.abort_order(oid)\n            self.log(f\"Commande {oid} annulée\", \"ok\")\n            self.refresh_orders_quietly()\n            return True, f\"❌ Commande <code>{esc(oid)}</code> annulée.\", True\n        if cmd in (\"reserver\", \"reserve\"):\n            item = args.get(\"item\") or (w[0] if w else \"\")\n            q = args.get(\"qty\") or (w[1] if len(w) > 1 else \"1\")\n            if not item:\n                return False, \"Usage : /reserver <id du panier> [quantité]\", False\n            q = min(3, max(1, int(q))) if str(q).isdigit() else 1\n            text = self.reserve(item, q)\n            if not text.startswith(\"❌\"):\n                self.refresh_orders_quietly()\n            return not text.startswith(\"❌\"), text, True\n        if cmd == \"horaires\":\n            m = re.match(r\"^(\\d{1,2})\\s*h?\\s*-\\s*(\\d{1,2})\\s*h?$\", str(args.get(\"text\", \"\")).strip().lower())\n            if not m:\n                return False, f\"Usage : /horaires 6h-22h (actuellement {s['hour_start']}h-{s['hour_end']}h)\", False\n            a, b = int(m.group(1)), int(m.group(2))\n            if not (0 <= a <= 23 and 1 <= b <= 24 and a != b):\n                return False, \"Heures invalides (0-23 pour le début, 1-24 pour la fin).\", False\n            s[\"hour_start\"], s[\"hour_end\"] = a, b\n            self.save_settings()\n            return True, f\"⏰ Plage de scan : {a}h → {b}h.\", False\n        if cmd in (\"fini\", \"done\", \"termine\"):\n            s[\"done_date\"] = f\"{now_paris():%Y-%m-%d}\"\n            self.save_settings()\n            self.log(\"Fini pour aujourd'hui : scans suspendus jusqu'à demain\", \"ok\")\n            return True, f\"✅ C'est noté, plus de scan aujourd'hui. Reprise demain à {s['hour_start']}h.\", False\n        if cmd in (\"stop\", \"pause\", \"arreter\"):\n            s[\"enabled\"] = False\n            self.save_settings()\n            self.log(\"Scans arrêtés (bouton Arrêter)\", \"warn\")\n            return True, \"⏹ Scans TGTG arrêtés. Reprends avec le bouton « Reprendre » ou /tgtg resume.\", False\n        if cmd in (\"resume\", \"reprendre\", \"start\"):\n            s[\"enabled\"] = True\n            s[\"done_date\"] = \"\"\n            self.fail_count = 0\n            self.last_ok = time.time()\n            self.save_settings()\n            self.log(\"Scans repris\", \"ok\")\n            return True, \"▶ Scans TGTG repris.\", False\n        if cmd == \"interval\":\n            if not w or not w[0].isdigit():\n                return False, f\"Usage : /interval 30 (secondes, minimum {MIN_INTERVAL}). Actuellement {s['interval']} s.\", False\n            s[\"interval\"] = max(MIN_INTERVAL, int(w[0]))\n            self.save_settings()\n            return True, f\"⏱ Intervalle : {s['interval']} s\" + (f\" (minimum {MIN_INTERVAL})\" if int(w[0]) < MIN_INTERVAL else \"\") + \".\", False\n        if cmd == \"auto\":\n            if w and w[0].isdigit():\n                s[\"auto_quantity\"] = min(3, max(1, int(w[0])))\n                s[\"auto_reserve\"] = True\n            else:\n                s[\"auto_reserve\"] = not s[\"auto_reserve\"]\n            self.save_settings()\n            return True, f\"🤖 Auto-réservation : {'✅ activée' if s['auto_reserve'] else '⛔ désactivée'} (quantité {s['auto_quantity']}).\", False\n        if cmd == \"set\":\n            k, v = str(args.get(\"key\", \"\")), str(args.get(\"value\", \"\")).strip()\n            try:\n                if k in (\"hour_start\", \"hour_end\"):\n                    h = int(v) % 24 if k == \"hour_start\" else min(24, max(1, int(v)))\n                    other = s[\"hour_end\" if k == \"hour_start\" else \"hour_start\"]\n                    if h % 24 == other % 24:\n                        return False, \"Le début et la fin de la plage ne peuvent pas être à la même heure.\", False\n                    s[k] = h\n                elif k == \"interval\": s[k] = max(MIN_INTERVAL, int(v))\n                elif k == \"auto_reserve\": s[k] = v in (\"1\", \"true\", \"Oui\", \"oui\")\n                elif k == \"auto_quantity\": s[k] = min(3, max(1, int(v)))\n                else: return False, f\"Réglage inconnu : {k}\", False\n            except ValueError:\n                return False, f\"Valeur invalide pour {k}\", False\n            self.save_settings()\n            return True, f\"Réglage {k} = {s[k]}\", False\n        if cmd == \"log\":\n            tail = \"\\n\".join(list(self.logbuf)[-10:]) or \"(vide)\"\n            return True, f\"📜 <b>Dernières lignes</b>\\n<pre>{esc(tail)}</pre>\", True\n        if cmd == \"ok\":\n            up = int(time.time() - self.started)\n            last = f\"il y a {int(time.time() - self.last_scan)} s\" if self.last_scan else \"jamais\"\n            return True, (f\"✅ TGTG tourne depuis {up // 3600} h {up % 3600 // 60} min\\n\"\n                          f\"Dernier scan : {last}\\nPlage : {s['hour_start']}h → {s['hour_end']}h \"\n                          f\"({'actif' if self.in_hours() else 'hors plage'})\\nIntervalle : {s['interval']} s\\n\"\n                          f\"Auto-réservation : {'✅' if s['auto_reserve'] else '⛔'} (x{s['auto_quantity']})\"), False\n        if cmd == \"reboot\":\n            self.reboot = True\n            return True, \"🔄 Redémarrage du bot TGTG…\", False\n        return False, f\"Commande inconnue pour TGTG : {cmd}\", False\n\n    def run_command(self, c):\n        try:\n            ok, text, html = self.handle(c)\n        except Exception as e:\n            ok, text, html = False, f\"Erreur : {str(e)[:200]}\", False\n            self.log(f\"Commande {c.get('cmd')} en erreur : {e}\", \"warn\")\n        self.hub.result(c[\"id\"], ok, text, html=html)\n\n    # ------------------------------------------------------------------ état pour l'interface\n    def state(self):\n        s = self.settings\n        with self.lock:\n            items = sorted(self.items.values(), key=lambda x: (-x[\"qty\"], x[\"name\"]))\n        avail = sum(1 for p in items if p[\"qty\"] > 0)\n        if self.fail_count >= 3 and s.get(\"enabled\", True):\n            status, summary = \"bad\", f\"Scans en échec ({self.fail_count} d'affilée)\"\n        elif not s.get(\"enabled\", True):\n            status, summary = \"idle\", \"Arrêté (bouton Reprendre pour relancer)\"\n        elif self.done_today():\n            status, summary = \"ok\", f\"Fini pour aujourd'hui, reprise demain à {s['hour_start']}h\"\n        elif not self.in_hours():\n            status, summary = \"ok\", f\"En veille (plage {s['hour_start']}h–{s['hour_end']}h)\"\n        elif not self.last_scan:\n            status, summary = \"idle\", \"Premier scan en cours\"\n        else:\n            status, summary = \"ok\", f\"{len(items)} favori(s), {avail} disponible(s)\"\n        up = int(time.time() - self.started)\n        return {\n            \"status\": status, \"summary\": summary,\n            \"metrics\": [\n                {\"label\": \"Favoris\", \"value\": str(len(items))}, {\"label\": \"Disponibles\", \"value\": str(avail)},\n                {\"label\": \"Plage\", \"value\": f\"{s['hour_start']}h–{s['hour_end']}h\"}, {\"label\": \"Intervalle\", \"value\": f\"{s['interval']} s\"},\n                {\"label\": \"Auto-résa\", \"value\": f\"{'oui' if s['auto_reserve'] else 'non'} (x{s['auto_quantity']})\"},\n                {\"label\": \"Dernier scan\", \"value\": f\"il y a {int(time.time() - self.last_scan)} s\" if self.last_scan else \"—\"},\n                {\"label\": \"Actif depuis\", \"value\": f\"{up // 3600} h {up % 3600 // 60} min\"},\n            ],\n            \"tables\": [\n                {\"title\": \"Favoris\", \"columns\": [\"Panier\", \"Dispo\", \"Prix\", \"Retrait\", \"Id\"], \"highlight\": 1,\n                 \"rows\": [[p[\"name\"], p[\"qty\"], f\"{p['price']:.2f} €\", p[\"pickup\"], p[\"id\"]] for p in items],\n                 \"rowActions\": [{\"action\": \"reserver\", \"label\": \"🛒 Réserver\", \"args\": {\"item\": \"{4}\", \"qty\": \"1\"}, \"when\": 1,\n                                 \"confirm\": \"Réserver 1 panier « {0} » ?\"}]},\n                {\"title\": \"Commandes actives (dernière lecture)\", \"columns\": [\"Panier\", \"État\", \"Numéro\"],\n                 \"rows\": [[((o.get(\"item\", {}) or {}).get(\"name\") or o.get(\"item_name\") or \"?\"), o.get(\"state\", \"?\"), o.get(\"id\", \"?\")] for o in self.orders],\n                 \"rowActions\": [{\"action\": \"annuler\", \"label\": \"Annuler\", \"args\": {\"order\": \"{2}\"}, \"danger\": True,\n                                 \"confirm\": \"Annuler la commande « {0} » ?\"}]},\n            ],\n            \"actions\": [\n                {\"id\": \"favoris\", \"label\": \"📋 Voir les favoris\"},\n                {\"id\": \"commandes\", \"label\": \"📦 Mes commandes\"},\n                {\"id\": \"scan\", \"label\": \"🔍 Scanner maintenant\"},\n                {\"id\": \"fini\", \"label\": \"✅ Panier pris, fini pour aujourd'hui\", \"confirm\": \"Arrêter les scans jusqu'à demain ?\"},\n                ({\"id\": \"stop\", \"label\": \"⏹ Arrêter les scans\", \"danger\": True, \"confirm\": \"Arrêter les scans TGTG ?\"} if s.get(\"enabled\", True)\n                 else {\"id\": \"resume\", \"label\": \"▶ Reprendre les scans\"}),\n                {\"id\": \"reserver\", \"label\": \"Réserver\", \"args\": [{\"name\": \"item\", \"label\": \"Id du panier\"}, {\"name\": \"qty\", \"label\": \"Quantité (1-3)\"}]},\n                {\"id\": \"annuler\", \"label\": \"Annuler une commande\", \"args\": [{\"name\": \"order\", \"label\": \"Numéro de commande\"}]},\n                {\"id\": \"reboot\", \"label\": \"🔄 Redémarrer le bot\", \"danger\": True, \"confirm\": \"Redémarrer le bot TGTG ?\"},\n            ],\n            \"settings\": [\n                {\"key\": \"hour_start\", \"label\": \"Début du scan (heure)\", \"type\": \"number\", \"value\": str(s[\"hour_start\"])},\n                {\"key\": \"hour_end\", \"label\": \"Fin du scan (heure)\", \"type\": \"number\", \"value\": str(s[\"hour_end\"])},\n                {\"key\": \"interval\", \"label\": \"Intervalle entre scans (s)\", \"type\": \"number\", \"value\": str(s[\"interval\"]), \"help\": f\"Minimum {MIN_INTERVAL} s : en dessous, risque de blocage.\"},\n                {\"key\": \"auto_reserve\", \"label\": \"Réservation automatique\", \"type\": \"bool\", \"value\": \"1\" if s[\"auto_reserve\"] else \"0\"},\n                {\"key\": \"auto_quantity\", \"label\": \"Paniers réservés automatiquement\", \"type\": \"select\", \"options\": [\"1\", \"2\", \"3\"], \"value\": str(s[\"auto_quantity\"])},\n            ],\n            \"log\": list(self.logbuf)[-40:],\n            \"telegram\": [],\n        }\n\n    # ------------------------------------------------------------------ boucle principale\n    def run(self):\n        self.connect()\n        threading.Thread(target=self.scan_loop, daemon=True).start()\n        self.hub.message(\n            f\"🟢 <b>TGTG démarré</b> (hub)\\nPlage : {self.settings['hour_start']}h → {self.settings['hour_end']}h · \"\n            f\"intervalle {self.settings['interval']} s · auto-résa {'✅' if self.settings['auto_reserve'] else '⛔'}\\n\"\n            \"Commandes : /menu pour tout voir.\", html=True)\n        last_state = 0.0\n        while not self.stop:\n            if time.time() - last_state > STATE_EVERY:\n                self.hub.flush(self.state())\n                last_state = time.time()\n            for c in self.hub.poll(wait=15):\n                self.run_command(c)\n                self.hub.flush(self.state())\n                last_state = time.time()\n                if self.reboot:\n                    self.log(\"Redémarrage demandé\")\n                    time.sleep(1)\n                    os._exit(0)  # systemd relance le service (Restart=always)\n        return 0\n\n\ndef main():\n    cfg = load_config()\n    try:\n        import tgtg as _tgtg_mod\n        from tgtg_scanner.tgtg_client import TgtgClient, normalize_cookie\n    except ImportError as e:\n        sys.exit(f\"Bibliotheque TGTG introuvable ({e})\")\n\n    ua = stable_user_agent()\n    print(f\"User-Agent TGTG: {ua}\", flush=True)\n\n    def factory(access_token, refresh_token, datadome_cookie, proxies):\n        # Client de la bibliothèque + UN user-agent récent et STABLE (la lib en tire un au hasard, avec une vieille\n        # version d'app si Google Play ne répond pas ; le cookie DataDome est lié au UA -> 403 à chaque redémarrage).\n        kw = dict(access_token=access_token, refresh_token=refresh_token, proxies=proxies,\n                  cookie=normalize_cookie(datadome_cookie) or \"datadome=init\",\n                  last_time_token_refreshed=datetime.now(),\n                  # la lib renouvellerait d'elle-même toutes les 4 h (via timedelta.seconds) : avec 86400 elle ne le fait\n                  # jamais, c'est refresh_if_due qui décide selon l'échéance réelle du jeton\n                  access_token_lifetime=86400)\n        try:\n            c = TgtgClient(user_agent=ua, **kw)\n        except TypeError:\n            c = TgtgClient(**kw)\n        try:\n            c.user_agent = ua\n            c.session.headers[\"user-agent\"] = ua\n        except Exception:\n            pass\n        return c\n\n    hub = Hub(\"tgtg\", \"Too Good To Go\", cfg, log=lambda m: print(m, flush=True))\n    bot = Bot(hub, cfg, factory)\n    bot.tgtg_mod = _tgtg_mod\n    bot.run()\n\n\nif __name__ == \"__main__\":\n    main()\n",
 "script_agent.py": "#!/usr/bin/env python3\n\"\"\"\nAgent « script » : branche sur le hub un programme qui tourne de temps en temps (ali-coins, MédinLyon...).\nConfiguration dans scripts.json (voir l'exemple écrit par l'installeur). Le hub peut :\n  - voir l'état du dernier passage (extrait du fichier journal du script) ;\n  - lancer le script tout de suite (« run ») et suivre son déroulement ;\n  - afficher la fin du journal.\nPlanning : champ facultatif « daily_at » (ex. \"09:30\", heure de Paris) = un passage automatique par jour,\nsans cron. Sans ce champ, l'agent ne programme rien (cron habituel ou bouton « Lancer »).\n\"\"\"\nimport json\nimport os\nimport re\nimport subprocess\nimport threading\nimport time\nfrom datetime import datetime\nfrom zoneinfo import ZoneInfo\n\nfrom hub_client import Hub, HERE, load_config\n\nPARIS = ZoneInfo(\"Europe/Paris\")\nANSI = re.compile(r\"\\x1b\\[[0-9;]*[A-Za-z]\")\nSTATE_EVERY = 30\n\n\ndef tail(path, n=200):\n    try:\n        with open(path, \"rb\") as f:\n            f.seek(0, 2)\n            size = f.tell()\n            f.seek(max(0, size - 60000))\n            lines = f.read().decode(\"utf8\", \"replace\").splitlines()\n        return [ANSI.sub(\"\", l) for l in lines[-n:]]\n    except OSError:\n        return []\n\n\ndef fmt_age(sec):\n    if sec < 90: return \"à l'instant\"\n    if sec < 3600: return f\"il y a {sec // 60} min\"\n    if sec < 86400: return f\"il y a {sec // 3600} h\"\n    return f\"il y a {sec // 86400} j\"\n\n\nclass ScriptBot:\n    def __init__(self, spec, cfg):\n        self.spec = spec\n        self.id = spec[\"id\"]\n        self.name = spec.get(\"name\", self.id)\n        self.cwd = os.path.expanduser(spec[\"cwd\"])\n        self.log_path = os.path.join(self.cwd, spec.get(\"log\", \"cron.log\"))\n        self.hub = Hub(self.id, self.name, cfg, log=lambda m: print(f\"[{self.id}] {m}\", flush=True))\n        self.proc = None\n        self.run_started = 0.0\n        self.last_run = {\"ts\": 0, \"code\": None, \"secs\": 0}\n        self.out = []\n        self.lock = threading.Lock()\n        self.stale_hours = float(spec.get(\"stale_hours\", 36))\n        self.auto_file = os.path.join(HERE, f\".auto_{self.id}\")\n\n    def auto_due(self):\n        \"\"\"Passage quotidien automatique : une fois par jour, à partir de daily_at (heure de Paris).\"\"\"\n        at = self.spec.get(\"daily_at\")\n        if not at or self.running():\n            return False\n        now = datetime.now(PARIS)\n        try:\n            hh, mm = (int(x) for x in str(at).split(\":\"))\n        except ValueError:\n            return False\n        if (now.hour, now.minute) < (hh, mm):\n            return False\n        try:\n            with open(self.auto_file, encoding=\"utf8\") as f:\n                if f.read().strip() == now.strftime(\"%Y-%m-%d\"):\n                    return False\n        except OSError:\n            pass\n        with open(self.auto_file, \"w\", encoding=\"utf8\") as f:\n            f.write(now.strftime(\"%Y-%m-%d\"))\n        return True\n\n    # ------------------------------------------------------------------ exécution\n    def running(self):\n        return self.proc is not None and self.proc.poll() is None\n\n    def start(self, args=\"\"):\n        if self.running():\n            return False, f\"{self.name} est déjà en cours d'exécution.\"\n        cmd = self.spec[\"run\"] + ((\" \" + args) if args else \"\")\n        self.out = []\n        try:\n            self.proc = subprocess.Popen(cmd, shell=True, cwd=self.cwd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,\n                                         text=True, errors=\"replace\", start_new_session=True)\n        except OSError as e:\n            return False, f\"Impossible de lancer : {e}\"\n        self.run_started = time.time()\n        threading.Thread(target=self._pump, daemon=True).start()\n        return True, f\"▶ {self.name} lancé. Je te dis quand c'est fini.\"\n\n    def _pump(self):\n        p = self.proc\n        for line in p.stdout:\n            line = ANSI.sub(\"\", line.rstrip(\"\\n\"))\n            self.out.append(line)\n            self.out = self.out[-300:]\n            try:  # le script ne journalise pas forcément dans le même fichier que le cron\n                with open(self.log_path, \"a\", encoding=\"utf8\") as f:\n                    f.write(line + \"\\n\")\n            except OSError:\n                pass\n        code = p.wait()\n        secs = int(time.time() - self.run_started)\n        self.last_run = {\"ts\": int(time.time()), \"code\": code, \"secs\": secs}\n        info = self.parse()\n        done_codes = (0, 2)  # 2 = déjà collecté aujourd'hui (ali-coins)\n        icon = \"✅\" if code in done_codes and info[\"status\"] != \"bad\" else \"🔴\"\n        self.hub.event(f\"Passage terminé (code {code}, {secs} s) : {info['summary']}\", \"ok\" if icon == \"✅\" else \"bad\")\n        self.hub.message(f\"{icon} {self.name} : passage terminé en {secs} s (code {code})\\n{info['summary']}\")\n        self.hub.flush(self.state())\n\n    # ------------------------------------------------------------------ lecture du journal\n    def parse(self):\n        lines = tail(self.log_path, 250) if not self.running() else self.out[-250:]\n        text = \"\\n\".join(lines)\n        metrics = []\n        for m in self.spec.get(\"metrics\", []):\n            hits = re.findall(m[\"regex\"], text, re.I)\n            if hits:\n                v = hits[-1]\n                metrics.append({\"label\": m[\"label\"], \"value\": (v if isinstance(v, str) else v[0]) + m.get(\"suffix\", \"\")})\n        last_err = max([i for i, l in enumerate(lines) if re.search(self.spec.get(\"error_regex\", r\"\\bERROR\\b|Traceback|\\bFAILED\\b\"), l)], default=-1)\n        last_ok = max([i for i, l in enumerate(lines) if re.search(self.spec.get(\"ok_regex\", r\"success|termin|done|OK\\b\"), l, re.I)], default=-1)\n        session_bad = bool(re.search(self.spec.get(\"session_regex\", r\"session.*(expir|invalid|invalide)|MANUAL_LOGIN|login required\"), text, re.I))\n        try:\n            mtime = os.path.getmtime(self.log_path)\n        except OSError:\n            mtime = 0\n        age = time.time() - mtime if mtime else None\n        if session_bad and last_err > last_ok:\n            status, summary = \"bad\", \"Session expirée : refais le login sur ton PC puis réimporte la session\"\n        elif age is None:\n            status, summary = \"idle\", \"Aucun journal pour le moment\"\n        elif last_err > last_ok:\n            err = ANSI.sub(\"\", lines[last_err])[:140]\n            status, summary = \"warn\", f\"Dernier passage avec erreur : {err}\"\n        elif age > self.stale_hours * 3600:\n            status, summary = \"warn\", f\"Pas de passage depuis {fmt_age(int(age))}\"\n        else:\n            status, summary = \"ok\", f\"Dernier passage {fmt_age(int(age))}\" + (\" · \" + \", \".join(f\"{m['label']} {m['value']}\" for m in metrics[:3]) if metrics else \"\")\n        return {\"status\": status, \"summary\": summary, \"metrics\": metrics, \"lines\": lines, \"age\": age}\n\n    # ------------------------------------------------------------------ commandes\n    def handle(self, c):\n        cmd = c[\"cmd\"]\n        if cmd in (\"run\", \"lancer\", \"start\"):\n            ok, text = self.start()\n            return ok, text, False\n        if cmd == \"dry\":\n            ok, text = self.start(self.spec.get(\"dry_args\", \"--dry-run --notify\"))\n            return ok, text, False\n        if cmd in (\"log\", \"journal\"):\n            lines = (self.out if self.running() else tail(self.log_path, 12))[-12:]\n            return True, \"📜 \" + (self.name + \"\\n\" + \"\\n\".join(lines) if lines else \"journal vide\"), False\n        if cmd in (\"status\", \"etat\", \"ok\"):\n            info = self.parse()\n            extra = \"\\n\".join(f\"• {m['label']} : {m['value']}\" for m in info[\"metrics\"])\n            return True, f\"{self.name}\\n{info['summary']}\" + (f\"\\n{extra}\" if extra else \"\") + (\"\\n⏳ en cours d'exécution\" if self.running() else \"\"), False\n        if cmd == \"stop\":\n            if self.running():\n                try:\n                    os.killpg(os.getpgid(self.proc.pid), 15)\n                except OSError:\n                    self.proc.terminate()\n                return True, \"⏹ Arrêt demandé.\", False\n            return False, \"Rien à arrêter.\", False\n        return False, f\"Commande inconnue pour {self.name} : {cmd}\", False\n\n    def state(self):\n        info = self.parse()\n        running = self.running()\n        status, summary = info[\"status\"], info[\"summary\"]\n        if running:\n            status, summary = \"ok\", f\"En cours depuis {int(time.time() - self.run_started)} s\"\n        return {\n            \"status\": status, \"summary\": summary,\n            \"metrics\": info[\"metrics\"] + ([{\"label\": \"Dernier lancement manuel\", \"value\": f\"{fmt_age(int(time.time() - self.last_run['ts']))} (code {self.last_run['code']})\"}] if self.last_run[\"ts\"] else []),\n            \"actions\": [a for a in [\n                {\"id\": \"run\", \"label\": \"Lancer maintenant\", \"confirm\": f\"Lancer {self.name} maintenant ?\"},\n                {\"id\": \"dry\", \"label\": \"Test à blanc\"} if self.spec.get(\"dry_args\", \"--dry-run --notify\") else None,\n                {\"id\": \"stop\", \"label\": \"Arrêter le passage en cours\"},\n            ] if a],\n            \"settings\": [],\n            \"tables\": [],\n            \"log\": (self.out if running else info[\"lines\"])[-40:],\n            \"telegram\": [],\n        }\n\n\ndef main():\n    cfg = load_config()\n    with open(os.path.join(HERE, \"scripts.json\"), encoding=\"utf8\") as f:\n        specs = json.load(f)\n    bots = [ScriptBot(s, cfg) for s in specs if os.path.isdir(os.path.expanduser(s[\"cwd\"]))]\n    if not bots:\n        raise SystemExit(\"scripts.json : aucun dossier existant.\")\n    last = {b.id: 0.0 for b in bots}\n\n    def serve(b):\n        while True:\n            try:  # une erreur imprévue (journal illisible, regex...) ne doit jamais rendre le bot muet\n                if b.auto_due():\n                    ok, text = b.start(\"--no-delay\" if \"--no-delay\" not in b.spec[\"run\"] else \"\")\n                    b.hub.event(\"Passage quotidien automatique : \" + text, \"ok\" if ok else \"bad\")\n                if time.time() - last[b.id] > STATE_EVERY:\n                    b.hub.flush(b.state())\n                    last[b.id] = time.time()\n                for c in b.hub.poll(wait=15):\n                    try:\n                        ok, text, html = b.handle(c)\n                    except Exception as e:  # une commande ne doit jamais tuer l'agent\n                        ok, text, html = False, f\"Erreur : {str(e)[:200]}\", False\n                    b.hub.result(c[\"id\"], ok, text, html=html)\n                    b.hub.flush(b.state())\n                    last[b.id] = time.time()\n            except Exception as e:\n                print(f\"[{b.id}] erreur inattendue : {e}\", flush=True)\n                time.sleep(10)\n\n    threads = [threading.Thread(target=serve, args=(b,), daemon=True) for b in bots]\n    for t in threads:\n        t.start()\n    for t in threads:\n        t.join()\n\n\nif __name__ == \"__main__\":\n    main()\n",
 "medinlyon.py": "#!/usr/bin/env python3\n\"\"\"\nAgent MédinLyon : tu coches « Aujourd'hui » et/ou « Demain » (rien n'est surveillé au départ). Pour chaque date, le bot relève\nles horaires, garde le dernier relevé, et te prévient sur Telegram UNIQUEMENT quand un créneau PLUS TÔT que le\nmeilleur connu apparaît. Un créneau plus tardif ou rien de neuf : silence.\n\nSource : GET https://medinlyon.fr/consultation/creneaux?centre=1&date=AAAA-MM-JJ\n(fragment HTML avec les horaires ; aucune session ni cookie n'est nécessaire pour LIRE les créneaux).\nLa réservation se fait sur la page normale (lien dans l'alerte) : elle demande une session et tes coordonnées,\ndonc elle reste manuelle. Bibliothèque standard seulement.\n\"\"\"\nfrom concurrent.futures import ThreadPoolExecutor\nimport html as htmlmod\nimport json\nimport os\nimport re\nimport threading\nimport time\nimport urllib.error\nimport urllib.request\nfrom datetime import date, datetime, timedelta\nfrom zoneinfo import ZoneInfo\n\nfrom hub_client import Hub, HERE, load_config\n\nPARIS = ZoneInfo(\"Europe/Paris\")\nBASE = \"https://medinlyon.fr\"\nBOOK_URL = BASE + \"/consultation/cabinet\"\nSETTINGS_FILE = os.path.join(HERE, \"medinlyon_config.json\")\nDATA_FILE = os.path.join(HERE, \"medinlyon_releves.json\")  # derniers relevés, conservés après redémarrage\nSTATE_EVERY = 30\nMIN_INTERVAL = 5\nDAYS_FR = [\"lun\", \"mar\", \"mer\", \"jeu\", \"ven\", \"sam\", \"dim\"]\nTIME_RE = re.compile(r\"\\b([01]?\\d|2[0-3])\\s*[:hH]\\s*([0-5]\\d)\\b\")\nUA = (\"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) \"\n      \"Chrome/124.0 Safari/537.36\")\n\n\ndef parse_slots(fragment):\n    \"\"\"Extrait les horaires (« 21:30 ») d'un fragment HTML de créneaux. Retourne une liste triée sans doublon.\"\"\"\n    text = re.sub(r\"<(script|style)\\b.*?</\\1>\", \" \", fragment or \"\", flags=re.S | re.I)\n    # un horaire peut figurer dans value=\"…\", un label ou le texte du bouton : on lit attributs + texte\n    attrs = \" \".join(re.findall(r'(?:value|data-[\\w-]+|title|aria-label)=\"([^\"]*)\"', text, flags=re.I))\n    visible = htmlmod.unescape(re.sub(r\"<[^>]+>\", \" \", text))\n    found = set()\n    for chunk in (visible, htmlmod.unescape(attrs)):\n        for h, m in TIME_RE.findall(chunk):\n            found.add(f\"{int(h):02d}:{m}\")\n    return sorted(found)\n\n\ndef fetch_day(centre, day, timeout=20):\n    url = f\"{BASE}/consultation/creneaux?centre={centre}&date={day:%Y-%m-%d}\"\n    req = urllib.request.Request(url, headers={\"User-Agent\": UA, \"Accept\": \"text/html,*/*\",\n                                               \"Accept-Language\": \"fr-FR,fr;q=0.9\", \"X-Requested-With\": \"XMLHttpRequest\"})\n    with urllib.request.urlopen(req, timeout=timeout) as r:\n        return r.read().decode(\"utf8\", \"replace\")\n\n\ndef label(day):\n    return f\"{DAYS_FR[day.weekday()]} {day:%d/%m}\"\n\n\n\ndef parse_date(txt, today=None):\n    \"\"\"« aujourd'hui », « demain », « 09/11 », « 9/11/2026 », « 2026-11-09 » -> date (jamais dans le passé).\"\"\"\n    today = today or datetime.now(PARIS).date()\n    t = str(txt or \"\").strip().lower().replace(\"’\", \"'\")\n    if t in (\"aujourd'hui\", \"aujourdhui\", \"auj\", \"today\", \"ce soir\", \"ce_soir\"):\n        return today\n    if t in (\"demain\", \"tomorrow\"):\n        return today + timedelta(days=1)\n    m = re.match(r\"^(\\d{4})-(\\d{1,2})-(\\d{1,2})$\", t)\n    if m:\n        y, mo, d = (int(x) for x in m.groups())\n    else:\n        m = re.match(r\"^(\\d{1,2})[/.\\-](\\d{1,2})(?:[/.\\-](\\d{2,4}))?$\", t)\n        if not m:\n            raise ValueError(\"date non comprise (exemples : aujourd'hui, demain, 09/11)\")\n        d, mo = int(m.group(1)), int(m.group(2))\n        y = int(m.group(3)) if m.group(3) else today.year\n        if y < 100:\n            y += 2000\n    try:\n        out = date(y, mo, d)\n    except ValueError:\n        raise ValueError(\"date impossible\")\n    if out < today:\n        raise ValueError(\"cette date est passée\")\n    return out\n\n\nclass Bot:\n    def __init__(self, hub, fetch=fetch_day):\n        self.hub = hub\n        self.fetch = fetch\n        self.lock = threading.Lock()\n        self.settings = self.load_settings()\n        self.data = self.load_data()        # \"AAAA-MM-JJ\" -> {\"times\": [...], \"best\": \"HH:MM\"|None, \"seen\": epoch, \"known\": bool}\n        self.last_scan = 0.0\n        self.last_ok = time.time()\n        self.fail_count = 0\n        self.down_alerted = False\n        self.started = time.time()\n        self.logbuf = []\n        self.wake = threading.Event()\n        self.scan_lock = threading.Lock()  # « Scanner maintenant » et la boucle ne doivent jamais scanner en même temps\n\n    # ------------------------------------------------------------------ outils\n    def log(self, msg, lvl=\"info\"):\n        line = f\"{datetime.now(PARIS):%H:%M:%S} {msg}\"\n        self.logbuf = (self.logbuf + [line])[-80:]\n        print(line, flush=True)\n        if lvl in (\"warn\", \"bad\", \"ok\"):\n            self.hub.event(msg, lvl)\n\n    def load_settings(self):\n        s = {\"enabled\": True, \"centre\": 1, \"interval\": 30, \"today\": False, \"tomorrow\": False}\n        try:\n            with open(SETTINGS_FILE, encoding=\"utf8\") as f:\n                s.update({k: v for k, v in json.load(f).items() if k in s})\n        except Exception:\n            pass\n        return self.clean(s)\n\n    @staticmethod\n    def clean(s):\n        s[\"enabled\"] = bool(s[\"enabled\"])\n        s[\"centre\"] = max(1, int(s[\"centre\"]))\n        s[\"interval\"] = max(MIN_INTERVAL, int(s[\"interval\"]))\n        s[\"today\"], s[\"tomorrow\"] = bool(s[\"today\"]), bool(s[\"tomorrow\"])\n        return s\n\n    def watched(self):\n        \"\"\"Dates surveillées : « aujourd'hui » et « demain » glissent avec le calendrier.\"\"\"\n        t = datetime.now(PARIS).date()\n        return [f\"{d:%Y-%m-%d}\" for d, on in ((t, self.settings[\"today\"]), (t + timedelta(days=1), self.settings[\"tomorrow\"])) if on]\n\n    def save_settings(self):\n        with open(SETTINGS_FILE, \"w\", encoding=\"utf8\") as f:\n            json.dump(self.settings, f, indent=2)\n\n    def load_data(self):\n        try:\n            with open(DATA_FILE, encoding=\"utf8\") as f:\n                return json.load(f)\n        except Exception:\n            return {}\n\n    def save_data(self):\n        try:\n            with open(DATA_FILE, \"w\", encoding=\"utf8\") as f:\n                json.dump(self.data, f, indent=1)\n        except OSError:\n            pass\n\n    def prune(self):\n        \"\"\"Les relevés de dates qui ne sont plus surveillées (passées ou décochées) sont oubliés.\"\"\"\n        w = self.watched()\n        self.data = {d: v for d, v in self.data.items() if d in w}\n\n    # ------------------------------------------------------------------ scan\n    def scan_once(self):\n        with self.scan_lock:\n            self._scan_once()\n\n    def _scan_once(self):\n        self.prune()\n        days = self.watched()\n        if not days:\n            self.last_scan = self.last_ok = time.time()\n            return\n        s = self.settings\n\n        def one(day):\n            try:\n                return day, parse_slots(self.fetch(s[\"centre\"], date.fromisoformat(day))), None\n            except (urllib.error.URLError, OSError, ValueError) as e:\n                return day, None, e\n\n        errors, last = 0, None\n        with ThreadPoolExecutor(max_workers=4) as ex:  # dates en parallèle\n            results = list(ex.map(one, days))\n        for day, times, err in results:\n            if err is not None:\n                errors, last = errors + 1, err\n                continue\n            self.record(day, times)\n        if errors == len(days):\n            raise RuntimeError(f\"MédinLyon injoignable ({type(last).__name__}: {str(last)[:80]})\")\n        self.last_scan = self.last_ok = time.time()\n        if self.fail_count >= 3 or self.down_alerted:\n            self.hub.message(\"✅ MédinLyon : les scans fonctionnent de nouveau.\")\n        self.fail_count, self.down_alerted = 0, False\n        self.save_data()\n\n    def record(self, day, times):\n        \"\"\"Enregistre le relevé d'une date et alerte si le meilleur (plus tôt) créneau s'est amélioré.\"\"\"\n        with self.lock:\n            prev = self.data.get(day) or {\"known\": False, \"best\": None, \"times\": []}\n            best = times[0] if times else None\n            self.data[day] = {\"times\": times, \"best\": best, \"seen\": int(time.time()), \"known\": True}\n        if not prev[\"known\"]:\n            self.log(f\"{label(date.fromisoformat(day))} : relevé de départ ({', '.join(times) or 'aucun créneau'})\")\n            return\n        if best and (prev[\"best\"] is None or best < prev[\"best\"]):\n            self.alert(day, best, prev[\"best\"], times)\n\n    def alert(self, day, best, before, times):\n        d = date.fromisoformat(day)\n        self.log(f\"Créneau plus tôt {label(d)} : {best} (avant : {before or 'aucun'})\", \"ok\")\n        self.hub.message(\n            f\"🩺 <b>MédinLyon : créneau plus tôt !</b>\\n📅 {label(d)}\\n⏰ <b>{best}</b>\"\n            + (f\" (le meilleur d'avant : {before})\" if before else \" (il n'y avait rien avant)\")\n            + f\"\\nTous les créneaux du jour : {', '.join(times)}\\n\\n\"\n            f'<a href=\"{BOOK_URL}\">Réserver sur MédinLyon</a>', html=True)\n        self.hub.flush(self.state())\n\n    def scan_loop(self):\n        while True:\n            if self.settings[\"enabled\"]:\n                try:\n                    self.scan_once()\n                except Exception as e:\n                    self.fail_count += 1\n                    self.log(f\"Scan en erreur ({self.fail_count}) : {str(e)[:150]}\", \"warn\")\n                    if time.time() - self.last_ok > 900 and not self.down_alerted:\n                        self.down_alerted = True\n                        self.hub.message(f\"🔴 MédinLyon : plus aucun scan réussi depuis 15 min ({str(e)[:100]}).\")\n            self.wake.wait(self.settings[\"interval\"])\n            self.wake.clear()\n\n    # ------------------------------------------------------------------ texte\n    def slots_text(self):\n        if not self.watched():\n            return \"📭 Rien n'est surveillé. Envoie /medinlyon aujourdhui ou /medinlyon demain (ou coche sur le site).\"\n        lines = [\"🩺 <b>MédinLyon</b>\\n\"]\n        for day in self.watched():\n            v = self.data.get(day)\n            lab = label(date.fromisoformat(day))\n            if not v:\n                lines.append(f\"• {lab} : relevé en cours…\")\n            elif v[\"times\"]:\n                lines.append(f\"• {lab} : <b>{v['best']}</b> au plus tôt ({', '.join(v['times'])})\")\n            else:\n                lines.append(f\"• {lab} : aucun créneau\")\n        lines.append(f'\\n<a href=\"{BOOK_URL}\">Réserver</a>')\n        return \"\\n\".join(lines)\n\n    # ------------------------------------------------------------------ commandes\n    def toggle(self, key, args_text=\"\"):\n        s = self.settings\n        t = args_text.strip().lower()\n        s[key] = True if t in (\"on\", \"oui\", \"1\") else False if t in (\"off\", \"non\", \"0\") else not s[key]\n        if s[key]:\n            s[\"enabled\"] = True\n        self.save_settings()\n        self.wake.set()\n        name = \"aujourd'hui\" if key == \"today\" else \"demain\"\n        return f\"{'✅ Surveillé' if s[key] else '⛔ Plus surveillé'} : {name}.\" + (\n            \" Je te préviens si un créneau plus tôt apparaît.\" if s[key] else \"\")\n\n    def handle(self, c):\n        cmd, args = c[\"cmd\"], c.get(\"args\") or {}\n        s = self.settings\n        raw = str(args.get(\"date\") or args.get(\"text\") or \"\").strip()\n        if cmd in (\"today\", \"aujourdhui\", \"auj\"):\n            return True, self.toggle(\"today\", raw), False\n        if cmd in (\"tomorrow\", \"demain\"):\n            return True, self.toggle(\"tomorrow\", raw), False\n        if cmd in (\"date\", \"ajouter\", \"add\", \"surveiller\", \"retirer\", \"remove\"):\n            try:\n                d = parse_date(raw)\n            except ValueError as e:\n                return False, f\"{e}. Utilise /medinlyon aujourdhui ou /medinlyon demain.\", False\n            gap = (d - datetime.now(PARIS).date()).days\n            if gap not in (0, 1):\n                return False, \"Seuls aujourd'hui et demain sont surveillés.\", False\n            return True, self.toggle(\"today\" if gap == 0 else \"tomorrow\", \"off\" if cmd in (\"retirer\", \"remove\") else \"on\"), False\n        if cmd in (\"creneaux\", \"slots\", \"scan\", \"status\", \"etat\", \"ok\", \"dates\"):\n            if cmd == \"scan\":\n                self.scan_once()\n            return True, self.slots_text(), True\n        if cmd in (\"pause\", \"stop\"):\n            s[\"enabled\"] = False\n            self.save_settings()\n            return True, \"⏸ Surveillance MédinLyon en pause.\", False\n        if cmd in (\"resume\", \"reprendre\", \"start\"):\n            s[\"enabled\"] = True\n            self.save_settings()\n            self.wake.set()\n            return True, \"▶ Surveillance MédinLyon reprise.\", False\n        if cmd == \"set\":\n            k, v = str(args.get(\"key\", \"\")), str(args.get(\"value\", \"\")).strip()\n            if k not in (\"enabled\", \"centre\", \"interval\"):\n                return False, f\"Réglage inconnu : {k}\", False\n            try:\n                s[k] = (v in (\"1\", \"true\", \"Oui\", \"oui\")) if k == \"enabled\" else int(v)\n                self.settings = self.clean(s)\n            except ValueError:\n                return False, f\"Valeur invalide pour {k}\", False\n            self.save_settings()\n            self.wake.set()\n            return True, f\"Réglage {k} = {self.settings[k]}\", False\n        if cmd == \"log\":\n            return True, \"📜 \" + (\"\\n\".join(self.logbuf[-10:]) or \"(vide)\"), False\n        return False, f\"Commande inconnue pour MédinLyon : {cmd}\", False\n\n    def run_command(self, c):\n        try:\n            ok, text, html = self.handle(c)\n        except Exception as e:\n            ok, text, html = False, f\"Erreur : {str(e)[:200]}\", False\n            self.log(f\"Commande {c.get('cmd')} en erreur : {e}\", \"warn\")\n        self.hub.result(c[\"id\"], ok, text, html=html)\n\n    # ------------------------------------------------------------------ état pour l'interface\n    def state(self):\n        s = self.settings\n        rows = []\n        for day in self.watched():\n            v = self.data.get(day)\n            lab = label(date.fromisoformat(day))\n            rows.append([lab, (v[\"best\"] or \"—\") if v else \"…\", \", \".join(v[\"times\"]) if v and v[\"times\"] else (\"aucun\" if v else \"relevé en cours\"),\n                         f\"il y a {int(time.time() - v['seen'])} s\" if v else \"—\"])\n        if not s[\"enabled\"]:\n            status, summary = \"idle\", \"En pause\"\n        elif not self.watched():\n            status, summary = \"idle\", \"Rien de surveillé : coche Aujourd'hui et/ou Demain\"\n        elif self.fail_count >= 3:\n            status, summary = \"bad\", f\"Scans en échec ({self.fail_count} d'affilée)\"\n        elif not self.last_scan:\n            status, summary = \"idle\", \"Premier relevé en cours\"\n        else:\n            status = \"ok\"\n            found = [r for r in rows if r[1] not in (\"—\", \"…\")]\n            summary = f\"{len(self.watched())} jour(s) · \" + (f\"meilleur créneau {found[0][0]} {found[0][1]}\" if found else \"aucun créneau pour le moment\")\n        return {\n            \"status\": status, \"summary\": summary,\n            \"metrics\": [\n                {\"label\": \"Jours surveillés\", \"value\": str(len(self.watched()))}, {\"label\": \"Intervalle\", \"value\": f\"{s['interval']} s\"},\n                {\"label\": \"Dernier scan\", \"value\": f\"il y a {int(time.time() - self.last_scan)} s\" if self.last_scan else \"—\"},\n            ],\n            \"tables\": [{\"title\": \"Jours surveillés\", \"columns\": [\"Jour\", \"Meilleur créneau\", \"Tous les créneaux\", \"Relevé\"], \"rows\": rows}],\n            \"actions\": [\n                {\"id\": \"today\", \"label\": (\"✅ Aujourd'hui surveillé (cliquer pour arrêter)\" if s[\"today\"] else \"Surveiller aujourd'hui\")},\n                {\"id\": \"tomorrow\", \"label\": (\"✅ Demain surveillé (cliquer pour arrêter)\" if s[\"tomorrow\"] else \"Surveiller demain\")},\n                {\"id\": \"scan\", \"label\": \"Scanner maintenant\"},\n                {\"id\": \"pause\" if s[\"enabled\"] else \"resume\", \"label\": \"Mettre en pause\" if s[\"enabled\"] else \"Reprendre\"},\n            ],\n            \"settings\": [\n                {\"key\": \"enabled\", \"label\": \"Surveillance active\", \"type\": \"bool\", \"value\": \"1\" if s[\"enabled\"] else \"0\"},\n                {\"key\": \"interval\", \"label\": \"Intervalle entre scans (s)\", \"type\": \"number\", \"value\": str(s[\"interval\"]),\n                 \"help\": f\"Minimum {MIN_INTERVAL} s. Plus c'est court, plus tu es prévenu vite (ex. 10 s).\"},\n                {\"key\": \"centre\", \"label\": \"Numéro du centre\", \"type\": \"number\", \"value\": str(s[\"centre\"])},\n            ],\n            \"log\": self.logbuf[-40:],\n            \"telegram\": [],\n        }\n\n    def run(self):\n        threading.Thread(target=self.scan_loop, daemon=True).start()\n        self.hub.message(\"🟢 <b>MédinLyon démarré</b> (hub)\\nChoisis aujourd'hui et/ou demain : /medinlyon aujourdhui · /medinlyon demain. Je te préviens seulement si un créneau plus tôt apparaît.\", html=True)\n        last_state = 0.0\n        while True:\n            if time.time() - last_state > STATE_EVERY:\n                self.hub.flush(self.state())\n                last_state = time.time()\n            for c in self.hub.poll(wait=15):\n                self.run_command(c)\n                self.hub.flush(self.state())\n                last_state = time.time()\n\n\ndef main():\n    cfg = load_config()\n    hub = Hub(\"medinlyon\", \"MédinLyon\", cfg, log=lambda m: print(m, flush=True))\n    Bot(hub).run()\n\n\nif __name__ == \"__main__\":\n    main()\n",
 "vinted_core.py": "\"\"\"\nMoteur des pépites Vinted : logique pure, sans réseau (testable).\n\nPrincipes (tirés des erreurs de la v1) :\n  - Un prix se calcule pour UN produit précis (« clé produit ») et jamais pour une recherche texte :\n    numéro de set Lego, série + tome + édition, jeu + console. Pas de clé = pas de prix = pas d'alerte.\n  - Les prix demandés des annonces en ligne surestiment le marché (ce qui reste en ligne est souvent trop cher).\n    Référence : médiane des VENTES constatées par le bot si on en a 3, sinon le 1er quartile des annonces en ligne.\n  - Aucun prix inventé : pas assez de comparables -> None -> l'annonce est ignorée.\n  - Frais réels 2026 : l'acheteur paie 0,70 € + 5 % + le port ; le vendeur particulier ne paie rien.\n\"\"\"\nimport re\nimport statistics\nimport unicodedata\n\n# ------------------------------------------------------------------ texte\n\nSTOP = {\n    \"le\", \"la\", \"les\", \"de\", \"du\", \"des\", \"un\", \"une\", \"et\", \"en\", \"au\", \"aux\", \"a\", \"the\", \"of\", \"and\",\n    \"jeu\", \"jeux\", \"video\", \"videos\", \"game\", \"games\", \"neuf\", \"neuve\", \"new\", \"occasion\", \"bon\", \"tres\", \"etat\",\n    \"comme\", \"parfait\", \"complet\", \"complete\", \"cib\", \"boite\", \"boitier\", \"notice\", \"avec\", \"sans\", \"pour\", \"fr\",\n    \"francais\", \"francaise\", \"version\", \"pal\", \"fra\", \"eur\", \"vf\", \"scelle\", \"scellee\", \"sealed\", \"blister\",\n    \"sous\", \"film\", \"envoi\", \"rapide\", \"livraison\", \"offerte\", \"vends\", \"vend\", \"vendu\", \"lot\", \"tome\", \"tomes\",\n    \"vol\", \"volume\", \"livre\", \"manga\", \"bd\", \"album\", \"edition\", \"nintendo\", \"sony\", \"playstation\", \"microsoft\",\n    \"console\", \"officiel\", \"officielle\", \"original\", \"originale\", \"rare\", \"top\",\n}\n\nPLATFORMS = [  # (motif, nom canonique) : du plus précis au plus général\n    (r\"\\bps ?5\\b|playstation ?5\", \"ps5\"), (r\"\\bps ?4\\b|playstation ?4\", \"ps4\"), (r\"\\bps ?3\\b|playstation ?3\", \"ps3\"),\n    (r\"\\bps ?2\\b|playstation ?2\", \"ps2\"), (r\"\\bps ?1\\b|\\bpsx\\b|\\bpsone\\b|playstation ?1\", \"ps1\"),\n    (r\"\\bpsp\\b\", \"psp\"), (r\"\\bps ?vita\\b\", \"vita\"),\n    (r\"\\bswitch ?2\\b\", \"switch2\"), (r\"\\bswitch\\b\", \"switch\"),\n    (r\"\\bxbox ?series\\b\", \"xboxseries\"), (r\"\\bxbox ?one\\b\", \"xboxone\"), (r\"\\bxbox ?360\\b\", \"xbox360\"), (r\"\\bxbox\\b\", \"xbox\"),\n    (r\"\\bgame ?boy ?advance\\b|\\bgba\\b\", \"gba\"), (r\"\\bgame ?boy ?color\\b|\\bgbc\\b\", \"gbc\"), (r\"\\bgame ?boy\\b|\\bgameboy\\b\", \"gb\"),\n    (r\"\\b3ds\\b|\\b2ds\\b\", \"3ds\"), (r\"\\bnintendo ds\\b|\\bds lite\\b|\\bdsi\\b|\\bds\\b\", \"ds\"),\n    (r\"\\bwii ?u\\b\", \"wiiu\"), (r\"\\bwii\\b\", \"wii\"), (r\"\\bgame ?cube\\b|\\bngc\\b\", \"gamecube\"), (r\"\\bn ?64\\b|nintendo 64\", \"n64\"),\n    (r\"\\bsuper nintendo\\b|\\bsnes\\b\", \"snes\"), (r\"\\bnes\\b\", \"nes\"),\n    (r\"\\bmega ?drive\\b|\\bgenesis\\b\", \"megadrive\"), (r\"\\bdreamcast\\b\", \"dreamcast\"), (r\"\\bsaturn\\b\", \"saturn\"),\n    (r\"\\bmaster system\\b\", \"mastersystem\"),\n]\nPLATFORM_WORDS = {\"ps5\", \"ps4\", \"ps3\", \"ps2\", \"ps1\", \"psx\", \"psp\", \"vita\", \"switch\", \"xbox\", \"series\", \"one\", \"360\",\n                  \"game\", \"boy\", \"gameboy\", \"advance\", \"color\", \"gba\", \"gbc\", \"gb\", \"3ds\", \"2ds\", \"ds\", \"lite\", \"dsi\",\n                  \"wii\", \"wiiu\", \"gamecube\", \"cube\", \"ngc\", \"n64\", \"64\", \"super\", \"snes\", \"nes\", \"mega\", \"drive\",\n                  \"megadrive\", \"genesis\", \"dreamcast\", \"saturn\", \"master\", \"system\", \"playstation\", \"x\", \"s\"}\n\n# Séries connues (manga + BD) : la plus longue gagne (« one punch man » avant « one piece »...)\nSERIES = sorted({\n    \"one piece\", \"naruto\", \"boruto\", \"bleach\", \"dragon ball\", \"dragon ball super\", \"hunter x hunter\", \"berserk\", \"vagabond\",\n    \"vinland saga\", \"fullmetal alchemist\", \"death note\", \"attack on titan\", \"l attaque des titans\", \"chainsaw man\",\n    \"demon slayer\", \"jujutsu kaisen\", \"my hero academia\", \"tokyo ghoul\", \"gunnm\", \"akira\", \"evangelion\", \"gantz\", \"claymore\",\n    \"fruits basket\", \"sailor moon\", \"saint seiya\", \"city hunter\", \"nicky larson\", \"jojo\", \"dorohedoro\", \"dungeon meshi\",\n    \"oyasumi punpun\", \"homunculus\", \"spy x family\", \"blue lock\", \"kingdom\", \"monster\", \"20th century boys\", \"pluto\",\n    \"uzumaki\", \"tomie\", \"gyo\", \"les decapitees\", \"cauchemars de mimi\", \"junji ito\",\n    \"tintin\", \"asterix\", \"lucky luke\", \"spirou\", \"gaston\", \"blake et mortimer\", \"xiii\", \"largo winch\", \"thorgal\",\n    \"lanfeust\", \"donjon\", \"les schtroumpfs\", \"yoko tsuno\", \"buck danny\", \"titeuf\", \"corto maltese\", \"blacksad\",\n    \"les vieux fourneaux\", \"la quete de l oiseau du temps\", \"valerian\", \"les tuniques bleues\", \"boule et bill\",\n    \"les legendaires\", \"seuls\", \"lastman\", \"mortelle adele\", \"l arabe du futur\", \"walking dead\", \"saga\",\n}, key=len, reverse=True)\n\nVARIANT = re.compile(r\"\\b(integrale|coffret|collector|edition deluxe|prestige|perfect edition|ultimate|edition originale|eo|\"\n                     r\"tirage de tete|numerote|dedicace|signe|grand format|steelbook|limited|limitee|big box)\\b\")\nTOME = re.compile(r\"\\b(?:t|tome|tomes|vol|volume|n|no|numero)\\s*\\.?\\s*0*(\\d{1,3})\\b\")\nYEAR = re.compile(r\"^(19[5-9]\\d|20[0-3]\\d)$\")\n\n# Annonces qui ne sont pas le produit (ou pas en entier) : rejet pur et simple\nJUNK = re.compile(r\"\\b(boite vide|boitier seul|boitier vide|jaquette seule|notice seule|sans (le )?jeu|sans cartouche|\"\n                  r\"pieces detachees|incomplet|incomplete|manque|manquant|replique|repro|reproduction|copie|faux|fake|\"\n                  r\"contrefacon|custom|compatible|moc|lot de|en lot|vrac|recherche|cherche|echange|hs|ne fonctionne pas|\"\n                  r\"pour pieces|defectueux|abime|dechire|non complet)\\b\")\n\n\ndef norm(text):\n    t = unicodedata.normalize(\"NFKD\", str(text or \"\").lower()).encode(\"ascii\", \"ignore\").decode()\n    t = t.replace(\"'\", \" \").replace(\"’\", \" \")\n    return re.sub(r\"[^a-z0-9]+\", \" \", t).strip()\n\n\ndef platform(t):\n    for rx, name in PLATFORMS:\n        if re.search(rx, t):\n            return name\n    return \"\"\n\n\ndef condition_group(status, title=\"\"):\n    \"\"\"'neuf' ou 'occ' : deux groupes seulement, sinon jamais assez de comparables.\"\"\"\n    s = norm(status) + \" \" + norm(title)\n    return \"neuf\" if re.search(r\"\\bneuf\\b|\\bscelle|\\bsealed\\b|\\bsous blister\\b|\\bjamais ouvert\\b\", s) else \"occ\"\n\n\n# ------------------------------------------------------------------ identité produit\n\ndef product_key(title):\n    \"\"\"Clé du produit (str) ou None quand on ne peut pas être sûr de ce que c'est.\"\"\"\n    t = norm(title)\n    if not t or JUNK.search(t):\n        return None\n    words = t.split()\n    variant = \"var\" if VARIANT.search(t) else \"std\"\n\n    if \"lego\" in words:\n        for w in words:\n            if w.isdigit() and 4 <= len(w) <= 7 and not YEAR.match(w):\n                return f\"lego:{w}\"\n        return None\n\n    if \"brio\" in words:\n        m = re.search(r\"\\b(33\\d{3})\\b\", t)\n        return f\"brio:{m.group(1)}\" if m else None\n\n    p = platform(t)\n    if p:\n        core = [w for w in words if w not in STOP and w not in PLATFORM_WORDS and not YEAR.match(w) and (len(w) > 1 or w.isdigit())]\n        core = sorted(set(core))[:6]\n        if not core:\n            return None  # « jeu switch » tout court : impossible à identifier\n        kind = \"console\" if \"console\" in words else \"jv\"\n        return f\"{kind}:{p}:{variant}:{' '.join(core)}\"\n\n    for s in SERIES:\n        if re.search(r\"\\b\" + re.escape(s) + r\"\\b\", t):\n            m = TOME.search(t)\n            if not m:\n                return None\n            if re.search(r\"\\b\\d{1,3}\\s*(a|-|et)\\s*\\d{1,3}\\b\", t):\n                return None  # plusieurs tomes = un lot\n            return f\"livre:{s.replace(' ', '_')}:{int(m.group(1))}:{variant}\"\n    return None\n\n\ndef category(key):\n    if not key:\n        return \"\"\n    head = key.split(\":\", 1)[0]\n    return {\"lego\": \"lego\", \"brio\": \"brio\", \"jv\": \"jeux_video\", \"console\": \"jeux_video\", \"livre\": \"livres\"}.get(head, head)\n\n\ndef search_text(key):\n    \"\"\"Requête courte pour chercher les comparables d'une clé (2-4 mots, jamais le titre brut).\"\"\"\n    parts = key.split(\":\")\n    if parts[0] == \"lego\":\n        return f\"lego {parts[1]}\"\n    if parts[0] == \"brio\":\n        return f\"brio {parts[1]}\"\n    if parts[0] == \"livre\":\n        return f\"{parts[1].replace('_', ' ')} tome {parts[2]}\"\n    if parts[0] in (\"jv\", \"console\"):\n        names = {\"ps1\": \"ps1\", \"gb\": \"game boy\", \"gba\": \"gba\", \"gbc\": \"game boy color\", \"xboxseries\": \"xbox series\",\n                 \"xboxone\": \"xbox one\", \"xbox360\": \"xbox 360\", \"wiiu\": \"wii u\", \"switch2\": \"switch 2\"}\n        return f\"{parts[3]} {names.get(parts[1], parts[1])}\"\n    return key\n\n\ndef same_product(a, b):\n    \"\"\"Les livres et Lego doivent avoir la même clé ; les jeux tolèrent un mot d'écart (titres très variables).\"\"\"\n    if not a or not b:\n        return False\n    if a == b:\n        return True\n    pa, pb = a.split(\":\", 3), b.split(\":\", 3)\n    if pa[0] not in (\"jv\", \"console\") or pa[:3] != pb[:3] or len(pa) < 4 or len(pb) < 4:\n        return False\n    ta, tb = set(pa[3].split()), set(pb[3].split())\n    inter = len(ta & tb)\n    return inter >= 2 and inter / len(ta | tb) >= 0.75\n\n\n# ------------------------------------------------------------------ prix\n\ndef _q(sorted_vals, q):\n    \"\"\"Quantile par interpolation linéaire (liste déjà triée).\"\"\"\n    if not sorted_vals:\n        return 0.0\n    pos = (len(sorted_vals) - 1) * q\n    lo, hi = int(pos), min(int(pos) + 1, len(sorted_vals) - 1)\n    return sorted_vals[lo] + (sorted_vals[hi] - sorted_vals[lo]) * (pos - lo)\n\n\ndef clean(prices):\n    \"\"\"Écarte les valeurs aberrantes (Tukey). Garde la liste si le nettoyage la vide trop.\"\"\"\n    s = sorted(p for p in prices if p and p > 0)\n    if len(s) < 4:\n        return s\n    q1, q3 = _q(s, 0.25), _q(s, 0.75)\n    iqr = q3 - q1\n    kept = [p for p in s if q1 - 1.5 * iqr <= p <= q3 + 1.5 * iqr]\n    return kept if len(kept) >= 3 else s\n\n\ndef market_price(active, sold, min_sold=3, min_active=4):\n    \"\"\"\n    Prix auquel on peut raisonnablement revendre, ou None.\n    active : prix demandés des annonces comparables en ligne ; sold : prix des comparables vendus (constatés).\n    \"\"\"\n    sold, active = clean(sold), clean(active)\n    if len(sold) >= min_sold:\n        ref, basis, base = statistics.median(sold), \"vendus\", sold\n    elif len(active) >= min_active:\n        ref, basis, base = _q(active, 0.25), \"en ligne (1er quartile)\", active\n    else:\n        return None\n    spread = (_q(base, 0.75) - _q(base, 0.25)) / statistics.median(base) if statistics.median(base) else 1.0\n    return {\"price\": round(ref, 2), \"basis\": basis, \"n_sold\": len(sold), \"n_active\": len(active),\n            \"spread\": round(spread, 2), \"low\": round(min(base), 2), \"high\": round(max(base), 2)}\n\n\ndef buyer_cost(price, ship_in, total_item_price=None):\n    \"\"\"Ce que tu paies vraiment : article + frais Vinted (0,70 € + 5 %) + port jusqu'à toi.\"\"\"\n    if total_item_price and total_item_price >= price:\n        return round(total_item_price + ship_in, 2)\n    return round(price + 0.70 + 0.05 * price + ship_in, 2)\n\n\ndef evaluate(price, market, s, total_item_price=None, favourites=0):\n    \"\"\"\n    Décide si c'est une pépite. s = réglages (profit_min, margin_min, discount, ship_in, conf_min).\n    Retourne un dict toujours renseigné ; 'ok' dit si on alerte, 'why' explique un refus.\n    \"\"\"\n    out = {\"ok\": False, \"why\": \"\", \"profit\": 0.0, \"margin\": 0.0, \"cost\": 0.0, \"resale\": 0.0, \"conf\": 0.0,\n           \"suspect\": False, \"score\": 0.0}\n    if not market:\n        out[\"why\"] = \"pas assez de comparables\"\n        return out\n    cost = buyer_cost(price, s[\"ship_in\"], total_item_price)\n    resale = market[\"price\"] * (1 - s[\"discount\"] / 100.0)\n    profit = resale - cost\n    margin = profit / cost * 100 if cost else 0\n    n = market[\"n_sold\"] * 2 + market[\"n_active\"]\n    conf = min(1.0, n / 10) * 0.5 + (0.3 if market[\"basis\"] == \"vendus\" else 0.0) + 0.2 * max(0.0, 1 - market[\"spread\"])\n    conf += 0.05 if favourites >= 5 else 0.0\n    suspect = price < 0.2 * market[\"price\"]  # trop beau : souvent une boîte vide, une notice, une arnaque\n    if suspect:\n        conf *= 0.85  # on prévient quand même : c'est aussi la tête des vraies pépites\n    out.update(cost=round(cost, 2), resale=round(resale, 2), profit=round(profit, 2), margin=round(margin, 1),\n               conf=round(min(conf, 1.0), 2), suspect=suspect, score=round(profit * min(conf, 1.0), 2))\n    if profit < s[\"profit_min\"]:\n        out[\"why\"] = f\"profit {profit:.2f} € < {s['profit_min']} €\"\n    elif margin < s[\"margin_min\"]:\n        out[\"why\"] = f\"marge {margin:.0f} % < {s['margin_min']} %\"\n    elif out[\"conf\"] < s[\"conf_min\"]:\n        out[\"why\"] = f\"confiance {out['conf']:.0%} trop faible\"\n    else:\n        out[\"ok\"] = True\n    return out\n",
 "vinted_source.py": "\"\"\"\nAccès à Vinted : une seule session HTTP qui imite Chrome (empreinte TLS/HTTP2 via curl_cffi), cookie de session\nrenouvelé tout seul. Lecture seule : recherche du catalogue et état d'une annonce. Aucun achat, aucun message.\n\"\"\"\nimport json\nimport random\nimport re\nimport threading\nimport time\n\ntry:\n    from curl_cffi import requests as cffi\nexcept ImportError:  # l'installeur l'ajoute ; sans lui Vinted répond 403 à coup sûr\n    cffi = None\n\nBASE = \"https://www.vinted.fr\"\n\n\nclass SourceError(Exception):\n    def __init__(self, code, msg=\"\"):\n        super().__init__(msg or f\"HTTP {code}\")\n        self.code = code\n\n\ndef _amount(v):\n    if isinstance(v, dict):\n        v = v.get(\"amount\")\n    try:\n        return float(str(v).replace(\",\", \".\"))\n    except (TypeError, ValueError):\n        return 0.0\n\n\ndef parse_item(it):\n    \"\"\"Annonce brute (JSON Vinted) -> dict simple. Les champs absents restent vides plutôt que de casser.\"\"\"\n    user = it.get(\"user\") or {}\n    photo = it.get(\"photo\") or {}\n    hr = photo.get(\"high_resolution\") or {}\n    iid = str(it.get(\"id\") or \"\")\n    return {\n        \"id\": iid,\n        \"title\": str(it.get(\"title\") or \"\").strip(),\n        \"price\": _amount(it.get(\"price\")),\n        \"total\": _amount(it.get(\"total_item_price\")),\n        \"status\": str(it.get(\"status\") or \"\"),\n        \"fav\": int(it.get(\"favourite_count\") or 0),\n        \"seller\": str(user.get(\"id\") or \"\"),\n        \"pro\": bool(user.get(\"business\")),\n        \"url\": str(it.get(\"url\") or f\"{BASE}/items/{iid}\"),\n        \"photo\": str(photo.get(\"url\") or \"\"),\n        \"ts\": int(hr.get(\"timestamp\") or 0),  # date de mise en ligne de la photo = âge réel de l'annonce\n        \"brand\": str(it.get(\"brand_title\") or \"\"),\n    }\n\n\nclass Vinted:\n    def __init__(self, proxy=None, min_gap=2.5):\n        self.proxy = proxy\n        self.min_gap = min_gap\n        self.session = None\n        self.lock = threading.Lock()\n        self.last_call = 0.0\n        self.last_status = \"jamais appelé\"\n        self.calls = 0\n        self.mode = \"api\"  # bascule sur \"html\" si Vinted refuse la route JSON du catalogue\n\n    def _new_session(self):\n        if cffi is None:\n            raise SourceError(0, \"curl_cffi manquant : relance l'installation de l'agent\")\n        s = cffi.Session(impersonate=\"chrome\")\n        if self.proxy:\n            s.proxies = {\"http\": self.proxy, \"https\": self.proxy}\n        s.headers.update({\"Accept-Language\": \"fr-FR,fr;q=0.9\", \"Accept\": \"application/json, text/plain, */*\"})\n        r = s.get(BASE + \"/\", timeout=25)\n        if r.status_code >= 400:\n            self.last_status = f\"page d'accueil : HTTP {r.status_code}\"\n            raise SourceError(r.status_code, self.last_status)\n        self.session = s\n\n    def _get(self, path, params=None, retry=True):\n        with self.lock:  # un seul appel à la fois, espacé et irrégulier\n            wait = self.min_gap * random.uniform(0.8, 1.6) - (time.time() - self.last_call)\n            if wait > 0:\n                time.sleep(wait)\n            try:\n                if self.session is None:\n                    self._new_session()\n                r = self.session.get(BASE + path, params=params, timeout=25)\n            except SourceError:\n                raise\n            except Exception as e:\n                self.session = None\n                self.last_status = f\"réseau : {type(e).__name__}\"\n                raise SourceError(0, self.last_status)\n            finally:\n                self.last_call = time.time()\n                self.calls += 1\n        if r.status_code == 401 and retry:  # cookie expiré : nouvelle session, un seul essai\n            self.session = None\n            return self._get(path, params, retry=False)\n        if r.status_code >= 400:\n            if r.status_code in (403, 429):\n                self.session = None\n            self.last_status = f\"{path.split('?')[0]} : HTTP {r.status_code}\"\n            raise SourceError(r.status_code, self.last_status)\n        self.last_status = \"OK\"\n        try:\n            return r.json()\n        except ValueError:\n            self.last_status = \"réponse non JSON (page anti-robot ?)\"\n            raise SourceError(200, self.last_status)\n\n    def search(self, text, order=\"newest_first\", per_page=96, price_from=None, price_to=None):\n        params = {\"search_text\": text, \"order\": order, \"per_page\": per_page, \"page\": 1}\n        if price_from:\n            params[\"price_from\"] = price_from\n        if price_to:\n            params[\"price_to\"] = price_to\n        if self.mode == \"api\":\n            try:\n                data = self._get(\"/api/v2/catalog/items\", params)\n                return [parse_item(i) for i in data.get(\"items\", []) if i.get(\"id\")]\n            except SourceError as e:\n                if e.code not in (404, 200):  # 403/429/réseau : vrai blocage, on ne change pas de méthode\n                    raise\n                self.mode = \"html\"  # route fermée ou réponse non JSON : pages publiques du catalogue\n        from urllib.parse import urlencode\n        code, html_text = self.page(\"/catalog?\" + urlencode({k: v for k, v in params.items() if k != \"per_page\"}))\n        if code >= 400:\n            raise SourceError(code, f\"catalogue HTML : HTTP {code}\")\n        items = parse_catalog_html(html_text)\n        if not items and \"/items/\" in html_text:\n            self.last_status = \"catalogue HTML illisible (format Vinted changé)\"\n            raise SourceError(200, self.last_status)\n        self.last_status = \"OK (pages HTML)\"\n        return items\n\n    def page(self, path):\n        \"\"\"Page HTML publique (statut HTTP, texte). 404 n'est pas une erreur ici : c'est une information.\"\"\"\n        with self.lock:\n            wait = self.min_gap * random.uniform(0.8, 1.6) - (time.time() - self.last_call)\n            if wait > 0:\n                time.sleep(wait)\n            try:\n                if self.session is None:\n                    self._new_session()\n                r = self.session.get(BASE + path, timeout=25, allow_redirects=True,\n                                     headers={\"Accept\": \"text/html,application/xhtml+xml\"})\n            except SourceError:\n                raise\n            except Exception as e:\n                self.session = None\n                self.last_status = f\"réseau : {type(e).__name__}\"\n                raise SourceError(0, self.last_status)\n            finally:\n                self.last_call = time.time()\n                self.calls += 1\n        if r.status_code in (403, 429) or r.status_code >= 500:\n            self.session = None\n            self.last_status = f\"page annonce : HTTP {r.status_code}\"\n            raise SourceError(r.status_code, self.last_status)\n        return r.status_code, r.text\n\n    def item_state(self, item_id):\n        \"\"\"\n        État d'une annonce lu sur sa page publique, comme le font les outils de suivi des ventes :\n          - données produit (JSON-LD) « SoldOut » / « OutOfStock »  -> 'sold'\n          - drapeau de réservation dans la page                    -> 'reserved'\n          - « InStock »                                           -> 'online'\n          - 404                                                   -> 'gone' (vendue OU supprimée : on ne sait pas)\n        L'ancienne route /api/v2/items/<id> n'est plus utilisable.\n        \"\"\"\n        code, text = self.page(f\"/items/{item_id}\")\n        return parse_item_page(code, text)\n\n\nAVAIL = re.compile(r'\"availability\"\\s*:\\s*\"(?:https?://schema\\.org/)?(\\w+)\"', re.I)\nRESERVED = re.compile(r'\\\\?\"is_reserved\\\\?\"\\s*:\\s*true', re.I)\n\n\ndef parse_item_page(code, text):\n    if code == 404:\n        return \"gone\"\n    if code >= 400:\n        return \"unknown\"\n    m = AVAIL.search(text or \"\")\n    avail = m.group(1).lower() if m else \"\"\n    if avail in (\"soldout\", \"outofstock\", \"discontinued\"):\n        return \"sold\"\n    if RESERVED.search(text or \"\"):\n        return \"reserved\"\n    if avail == \"instock\":\n        return \"online\"\n    return \"unknown\"\n\n\n_ITEM_START = re.compile(r'\\{\"id\":(\\d{6,}),')\n\n\ndef _field(chunk, rx, default=\"\"):\n    m = re.search(rx, chunk)\n    return m.group(1) if m else default\n\n\ndef parse_catalog_html(text):\n    \"\"\"\n    Annonces d'une page /catalog : Vinted embarque les données des articles (JSON, souvent échappé) dans la page.\n    Lecture tolérante champ par champ, bornée à chaque objet article, pour survivre à l'ordre des champs.\n    \"\"\"\n    t = (text or \"\").replace('\\\\\"', '\"').replace(\"\\\\u0026\", \"&\")\n    starts = [m for m in _ITEM_START.finditer(t)]\n    out, seen = [], set()\n    for i, m in enumerate(starts):\n        end = starts[i + 1].start() if i + 1 < len(starts) else m.start() + 4000\n        chunk = t[m.start():min(end, m.start() + 4000)]\n        title = _field(chunk, r'\"title\":\"((?:[^\"\\\\]|\\\\.)*)\"')\n        price = _field(chunk, r'\"price\":\\{[^}]*?\"amount\":\"?([\\d.]+)')\n        iid = m.group(1)\n        if not title or not price or iid in seen:\n            continue  # pas un article (ex. objet utilisateur ou photo)\n        seen.add(iid)\n        try:\n            title = json.loads('\"' + title + '\"')\n        except ValueError:\n            pass\n        out.append(parse_item({\n            \"id\": iid, \"title\": title, \"price\": {\"amount\": price},\n            \"total_item_price\": {\"amount\": _field(chunk, r'\"total_item_price\":\\{[^}]*?\"amount\":\"?([\\d.]+)', \"0\")},\n            \"status\": _field(chunk, r'\"status\":\"([^\"]*)\"'),\n            \"favourite_count\": _field(chunk, r'\"favourite_count\":(\\d+)', \"0\"),\n            \"user\": {\"id\": _field(chunk, r'\"user\":\\{[^{}]*?\"id\":(\\d+)'),\n                     \"business\": _field(chunk, r'\"business\":(true|false)') == \"true\"},\n            \"photo\": {\"high_resolution\": {\"timestamp\": _field(chunk, r'\"timestamp\":(\\d{9,})', \"0\")}},\n            \"url\": _field(chunk, r'\"url\":\"(https://www\\.vinted\\.[a-z.]+/items/[^\"]+)\"'),\n            \"brand_title\": _field(chunk, r'\"brand_title\":\"([^\"]*)\"'),\n        }))\n    return out\n",
 "vinted_hub.py": "#!/usr/bin/env python3\n\"\"\"\nAgent « Vinted pépites » pour le hub : repère les annonces Vinted vendues nettement sous leur prix de revente.\n\nApproche « apprentissage » : peu d'alertes, mais fondées sur des semaines d'observation.\n  1. Chaque annonce est rattachée à un produit précis (set Lego, série + tome, jeu + console) ; sinon elle est ignorée.\n  2. Chaque produit rencontré ouvre un DOSSIER : le bot relève ses comparables toutes les 6 h et les suit jusqu'à leur\n     vente. Il apprend ainsi le vrai prix de vente et le délai de revente de ce produit.\n  3. Tant qu'un dossier n'est pas mûr (N ventes constatées ET N jours d'observation), le produit ne déclenche AUCUNE alerte.\n  4. Produit mûr : coût réel (prix + 0,70 € + 5 % + port) contre médiane des ventes constatées (moins une décote),\n     revente rapide exigée. Il réanalyse aussi une annonce connue dont le prix baisse.\nAlerte Telegram (via le hub) avec « Ouvrir l'annonce », « Acheté », « Faux positif ». Le bot n'achète jamais rien.\n\"\"\"\nimport html\nimport json\nimport os\nimport random\nimport sqlite3\nimport threading\nimport time\nfrom collections import deque\nfrom datetime import datetime\nfrom zoneinfo import ZoneInfo\n\nfrom hub_client import Hub, HERE, load_config\nimport vinted_core as core\nfrom vinted_source import SourceError, Vinted\n\nPARIS = ZoneInfo(\"Europe/Paris\")\nCONFIG_FILE = os.path.join(HERE, \"vinted_config.json\")\nDB_FILE = os.path.join(HERE, \"vinted.db\")\nSTATE_EVERY = 30\nPRIO_EVERY = {\"haute\": 1, \"moyenne\": 4, \"basse\": 15}  # un tour sur N\nMARKET_TTL = 6 * 3600\nDAY = 86400\n\nDEFAULT_QUERIES = [\n    (\"jeu switch\", \"haute\"), (\"jeu ps5\", \"haute\"), (\"jeu ps4\", \"moyenne\"), (\"jeu game boy\", \"haute\"),\n    (\"jeu gameboy advance\", \"haute\"), (\"jeu snes\", \"haute\"), (\"jeu nes\", \"moyenne\"), (\"jeu n64\", \"haute\"),\n    (\"jeu gamecube\", \"haute\"), (\"jeu ps1\", \"moyenne\"), (\"jeu ps2\", \"moyenne\"), (\"jeu ds\", \"moyenne\"), (\"jeu 3ds\", \"moyenne\"),\n    (\"lego technic\", \"haute\"), (\"lego star wars\", \"haute\"), (\"lego creator\", \"haute\"), (\"lego icons\", \"haute\"),\n    (\"brio\", \"moyenne\"),\n    (\"manga tome\", \"basse\"), (\"berserk tome\", \"basse\"), (\"vagabond tome\", \"basse\"), (\"junji ito\", \"basse\"),\n    (\"bd edition originale\", \"basse\"), (\"spirou\", \"basse\"), (\"donjon trondheim\", \"basse\"),\n    # fautes de frappe : annonces vues par très peu d'acheteurs\n    (\"lgo\", \"basse\"), (\"nitendo switch\", \"basse\"), (\"pokemon jeux ds\", \"basse\"),\n]\nDEFAULT_SETTINGS = {\n    \"enabled\": True, \"alerts\": True,\n    \"profit_min\": 8.0, \"margin_min\": 40.0, \"conf_min\": 0.45,\n    \"discount\": 10.0,     # % retiré au prix de revente pour la négociation / la vente rapide\n    \"ship_in\": 3.5,       # port payé pour te faire livrer (€)\n    \"max_price\": 300.0, \"min_price\": 2.0,\n    \"cheap_cap\": 7.0,     # Lego et Brio : seulement les annonces à ce prix ou moins\n    \"gap\": 3.0,           # secondes minimum entre deux appels Vinted\n    \"max_age_h\": 48,      # une annonce plus vieille n'est analysée que si son prix baisse\n    \"min_sold\": 5,        # dossier mûr : au moins N ventes constatées...\n    \"min_days\": 21,       # ... et au moins N jours d'observation du produit\n    \"max_sell_days\": 30,  # on n'alerte que sur ce qui se revend vite (délai médian constaté)\n    \"auto_track\": True,   # ouvrir un dossier pour chaque produit rencontré dans les recherches\n    \"max_products\": 400,\n}\nNUM_SETTINGS = {\"profit_min\", \"margin_min\", \"conf_min\", \"discount\", \"ship_in\", \"max_price\", \"min_price\", \"cheap_cap\", \"gap\",\n                \"max_age_h\", \"min_sold\", \"min_days\", \"max_sell_days\", \"max_products\"}\nREFRESH_EVERY = 6 * 3600\nIGNORE = (\"lot de\", \"en lot\", \"vrac\", \"recherche\", \"echange\")\n\n\ndef esc(s):\n    return html.escape(str(s), quote=False)\n\n\ndef eur(x):\n    return f\"{x:.2f} €\".replace(\".\", \",\")\n\n\nclass Store:\n    \"\"\"SQLite local : annonces vues, comparables, ventes constatées, prix calculés, retours.\"\"\"\n\n    def __init__(self, path=DB_FILE):\n        self.db = sqlite3.connect(path, check_same_thread=False, timeout=30)\n        self.db.row_factory = sqlite3.Row\n        self.lock = threading.Lock()\n        with self.lock, self.db:\n            self.db.executescript(\"\"\"\n            PRAGMA journal_mode=WAL;\n            CREATE TABLE IF NOT EXISTS listings (\n              id TEXT PRIMARY KEY, key TEXT, cond TEXT, title TEXT, price REAL, seller TEXT, url TEXT, ts INTEGER,\n              first_seen INTEGER, last_seen INTEGER, last_check INTEGER DEFAULT 0, state TEXT DEFAULT 'online',\n              sold_at INTEGER, sold_price REAL, origin TEXT);\n            CREATE INDEX IF NOT EXISTS i_key ON listings(key, cond, state);\n            CREATE INDEX IF NOT EXISTS i_check ON listings(state, last_seen);\n            CREATE TABLE IF NOT EXISTS market (key TEXT, cond TEXT, at INTEGER, data TEXT, PRIMARY KEY (key, cond));\n            CREATE TABLE IF NOT EXISTS deals (id TEXT PRIMARY KEY, at INTEGER, data TEXT, verdict TEXT);\n            CREATE TABLE IF NOT EXISTS feedback (key TEXT, seller TEXT, kind TEXT, at INTEGER);\n            CREATE TABLE IF NOT EXISTS products (key TEXT PRIMARY KEY, label TEXT, origin TEXT, added_at INTEGER,\n              last_refresh INTEGER DEFAULT 0);\n            \"\"\")\n\n    def q(self, sql, args=(), one=False):\n        with self.lock:\n            cur = self.db.execute(sql, args)\n            return cur.fetchone() if one else cur.fetchall()\n\n    def x(self, sql, args=()):\n        with self.lock, self.db:\n            self.db.execute(sql, args)\n\n    def get(self, iid):\n        return self.q(\"SELECT * FROM listings WHERE id = ?\", (iid,), one=True)\n\n    def upsert(self, it, key, cond, origin, now):\n        with self.lock, self.db:\n            self.db.execute(\n                \"\"\"INSERT INTO listings (id, key, cond, title, price, seller, url, ts, first_seen, last_seen, origin)\n                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)\n                   ON CONFLICT(id) DO UPDATE SET price = excluded.price, last_seen = excluded.last_seen,\n                     key = COALESCE(listings.key, excluded.key), state = CASE WHEN listings.state = 'gone' THEN 'online' ELSE listings.state END\"\"\",\n                (it[\"id\"], key, cond, it[\"title\"][:200], it[\"price\"], it[\"seller\"], it[\"url\"], it[\"ts\"], now, now, origin))\n\n    def sold_rows(self, key, cond, since):\n        head = key.rsplit(\":\", 1)[0] + \":%\" if key.startswith((\"jv:\", \"console:\")) else key\n        rows = self.q(\"\"\"SELECT key, sold_price, sold_at, ts, first_seen FROM listings\n                         WHERE key LIKE ? AND cond = ? AND state = 'sold' AND sold_at > ?\"\"\", (head, cond, since))\n        return [r for r in rows if r[\"sold_price\"] and core.same_product(key, r[\"key\"])]\n\n    def sold_prices(self, key, cond, since):\n        return [r[\"sold_price\"] for r in self.sold_rows(key, cond, since)]\n\n    def excluded(self, key, seller):\n        k = self.q(\"SELECT COUNT(*) n FROM feedback WHERE kind = 'fp' AND key = ?\", (key,), one=True)[\"n\"]\n        s = self.q(\"SELECT COUNT(*) n FROM feedback WHERE kind = 'fp' AND seller = ? AND seller != ''\", (seller,), one=True)[\"n\"]\n        return k >= 2 or s >= 3\n\n\nclass Bot:\n    def __init__(self, hub, source=None, store=None, config_file=CONFIG_FILE, clock=time.time):\n        self.hub = hub\n        self.clock = clock\n        self.config_file = config_file\n        self.store = store or Store()\n        self.lock = threading.RLock()\n        self.logbuf = deque(maxlen=200)\n        self.load_config()\n        self.src = source or Vinted(proxy=self.proxy_from(hub.cfg), min_gap=self.s[\"gap\"])\n        self.round = 0\n        self.started = clock()\n        self.last_scan = 0.0\n        self.backoff = 0\n        self.problem = \"\"\n        self.stats = {\"seen\": 0, \"analysed\": 0, \"priced\": 0, \"deals\": 0, \"drops\": 0, \"sold_found\": 0}\n        self.stop = False\n        self.wake = threading.Event()\n\n    # ------------------------------------------------------------------ réglages\n    @staticmethod\n    def proxy_from(cfg):\n        \"\"\"Proxy facultatif : \"vinted\": {\"proxy\": \"http://user:pass@hote:port\"} dans hub.json. Sans lui, connexion directe.\"\"\"\n        return ((cfg or {}).get(\"vinted\") or {}).get(\"proxy\") or None\n\n    def load_config(self):\n        try:\n            with open(self.config_file, encoding=\"utf8\") as f:\n                raw = json.load(f)\n        except (OSError, ValueError):\n            raw = {}\n        self.s = {**DEFAULT_SETTINGS, **(raw.get(\"settings\") or {})}\n        qs = raw.get(\"queries\")\n        if not isinstance(qs, list):\n            qs = [{\"q\": q, \"prio\": p, \"seeded\": False} for q, p in DEFAULT_QUERIES]\n        self.queries = [q for q in qs if isinstance(q, dict) and q.get(\"q\")]\n        for q in self.queries:\n            q.setdefault(\"prio\", \"moyenne\")\n            q.setdefault(\"seeded\", False)\n            q.setdefault(\"found\", 0)\n        self.save_config()\n\n    def save_config(self):\n        tmp = self.config_file + \".tmp\"\n        with open(tmp, \"w\", encoding=\"utf8\") as f:\n            json.dump({\"settings\": self.s, \"queries\": self.queries}, f, indent=1, ensure_ascii=False)\n        os.replace(tmp, self.config_file)\n\n    def log(self, msg, lvl=\"info\"):\n        line = f\"{datetime.now(PARIS):%d/%m %H:%M:%S} {msg}\"\n        self.logbuf.append(line)\n        print(line, flush=True)\n        if lvl != \"info\":\n            self.hub.event(msg, lvl)\n\n    # ------------------------------------------------------------------ dossiers produits\n    def track(self, key, label, origin=\"auto\"):\n        if not key:\n            return False\n        if self.store.q(\"SELECT 1 FROM products WHERE key = ?\", (key,), one=True):\n            return True\n        n = self.store.q(\"SELECT COUNT(*) n FROM products\", one=True)[\"n\"]\n        if origin == \"auto\" and n >= self.s[\"max_products\"]:\n            return False\n        self.store.x(\"INSERT OR IGNORE INTO products (key, label, origin, added_at) VALUES (?, ?, ?, ?)\",\n                     (key, label[:80], origin, int(self.clock())))\n        return True\n\n    def maybe_track(self, key, label):\n        \"\"\"Un produit qui revient (3 annonces distinctes) mérite un dossier ; un titre isolé, non.\"\"\"\n        if self.store.q(\"SELECT 1 FROM products WHERE key = ?\", (key,), one=True):\n            return\n        if key.startswith((\"jv:\", \"console:\")):\n            head = key.rsplit(\":\", 1)[0] + \":%\"\n            rows = self.store.q(\"SELECT key FROM listings WHERE key LIKE ?\", (head,))\n            n = sum(1 for r in rows if core.same_product(key, r[\"key\"]))\n        else:\n            n = self.store.q(\"SELECT COUNT(*) n FROM listings WHERE key = ?\", (key,), one=True)[\"n\"]\n        if n >= 3:\n            self.track(key, label)\n\n    def dossier(self, key, cond):\n        \"\"\"Ce que le bot a appris sur un produit : ventes, prix, délai de revente, maturité.\"\"\"\n        now = int(self.clock())\n        p = self.store.q(\"SELECT * FROM products WHERE key = ?\", (key,), one=True)\n        rows = self.store.sold_rows(key, cond, now - 120 * DAY)\n        prices = sorted(r[\"sold_price\"] for r in rows)\n        delays = sorted(max(0, (r[\"sold_at\"] - (r[\"ts\"] or r[\"first_seen\"]))) / DAY for r in rows)\n        days = (now - p[\"added_at\"]) / DAY if p else 0\n        mid = lambda v: v[len(v) // 2] if v else None  # noqa: E731\n        ready = bool(p) and len(prices) >= self.s[\"min_sold\"] and days >= self.s[\"min_days\"]\n        return {\"key\": key, \"cond\": cond, \"tracked\": bool(p), \"days\": days, \"n_sold\": len(prices),\n                \"median\": mid(prices), \"delay\": mid(delays), \"ready\": ready}\n\n    def learn_step(self, limit=2):\n        \"\"\"Relève les comparables des dossiers les moins récemment mis à jour (pour les suivre jusqu'à leur vente).\"\"\"\n        now = int(self.clock())\n        rows = self.store.q(\"SELECT key FROM products WHERE last_refresh < ? ORDER BY last_refresh LIMIT ?\",\n                            (now - REFRESH_EVERY, limit))\n        for r in rows:\n            self.store.x(\"DELETE FROM market WHERE key = ?\", (r[\"key\"],))\n            self.market(r[\"key\"], \"occ\")  # enregistre aussi les comparables neufs\n            self.store.x(\"UPDATE products SET last_refresh = ? WHERE key = ?\", (now, r[\"key\"]))\n\n    # ------------------------------------------------------------------ analyse\n    def accept(self, it):\n        t = core.norm(it[\"title\"])\n        if it[\"pro\"] or not it[\"title\"]:\n            return False\n        if not (self.s[\"min_price\"] <= it[\"price\"] <= self.s[\"max_price\"]):\n            return False\n        return not any(w in t for w in IGNORE)\n\n    def market(self, key, cond, exclude_id=\"\", exclude_seller=\"\"):\n        now = int(self.clock())\n        row = self.store.q(\"SELECT at, data FROM market WHERE key = ? AND cond = ?\", (key, cond), one=True)\n        if row and now - row[\"at\"] < MARKET_TTL:\n            return json.loads(row[\"data\"]) if row[\"data\"] else None\n        comps = self.src.search(core.search_text(key), order=\"relevance\")\n        active = []\n        for c in comps:\n            ck = core.product_key(c[\"title\"])\n            if not core.same_product(key, ck) or c[\"pro\"]:\n                continue\n            ccond = core.condition_group(c[\"status\"], c[\"title\"])\n            self.store.upsert(c, ck, ccond, \"comparable\", now)  # suivi jusqu'à la vente\n            if ccond == cond and c[\"id\"] != exclude_id and c[\"seller\"] != exclude_seller:\n                active.append(c[\"price\"])\n        m = core.market_price(active, self.store.sold_prices(key, cond, now - 90 * DAY))\n        self.store.x(\"INSERT OR REPLACE INTO market (key, cond, at, data) VALUES (?, ?, ?, ?)\",\n                     (key, cond, now, json.dumps(m) if m else \"\"))\n        return m\n\n    def analyse(self, it, query, drop_from=None):\n        key = core.product_key(it[\"title\"])\n        if not key:\n            return None\n        cat = core.category(key)\n        if cat in (\"lego\", \"brio\") and it[\"price\"] > self.s[\"cheap_cap\"]:\n            return None\n        if self.store.excluded(key, it[\"seller\"]):\n            return None\n        self.stats[\"analysed\"] += 1\n        cond = core.condition_group(it[\"status\"], it[\"title\"])\n        dos = self.dossier(key, cond)\n        if not dos[\"ready\"]:\n            self.stats[\"learning\"] = self.stats.get(\"learning\", 0) + 1\n            return None  # dossier trop jeune : on apprend, on ne parle pas\n        if dos[\"delay\"] is not None and dos[\"delay\"] > self.s[\"max_sell_days\"]:\n            return None  # se revend trop lentement\n        self.market(key, cond, it[\"id\"], it[\"seller\"])  # garde les comparables à jour (suivi des ventes)\n        sold = self.store.sold_prices(key, cond, int(self.clock()) - 120 * DAY)\n        m = core.market_price([], sold, min_sold=int(self.s[\"min_sold\"]))\n        if m:\n            self.stats[\"priced\"] += 1\n            m[\"delay\"] = dos[\"delay\"]\n            m[\"days\"] = round(dos[\"days\"])\n        ev = core.evaluate(it[\"price\"], m, self.s, total_item_price=it[\"total\"] or None, favourites=it[\"fav\"])\n        if not ev[\"ok\"]:\n            return None\n        if self.store.q(\"SELECT 1 FROM deals WHERE id = ?\", (it[\"id\"],), one=True) and not drop_from:\n            return None\n        deal = {\"id\": it[\"id\"], \"title\": it[\"title\"], \"url\": it[\"url\"], \"price\": it[\"price\"], \"key\": key, \"cat\": cat,\n                \"cond\": cond, \"query\": query, \"market\": m, \"ev\": ev, \"drop_from\": drop_from, \"seller\": it[\"seller\"]}\n        self.store.x(\"INSERT OR REPLACE INTO deals (id, at, data, verdict) VALUES (?, ?, ?, COALESCE((SELECT verdict FROM deals WHERE id = ?), ''))\",\n                     (it[\"id\"], int(self.clock()), json.dumps(deal, ensure_ascii=False), it[\"id\"]))\n        self.stats[\"deals\"] += 1\n        for q in self.queries:\n            if q[\"q\"] == query:\n                q[\"found\"] = q.get(\"found\", 0) + 1\n        self.log(f\"💎 {it['title'][:60]} : {eur(it['price'])} -> profit {eur(ev['profit'])}\", \"ok\")\n        if self.s[\"alerts\"]:\n            self.hub.message(self.deal_text(deal), html=True, markup=self.deal_buttons(deal))\n        return deal\n\n    @staticmethod\n    def deal_text(d):\n        ev, m = d[\"ev\"], d[\"market\"]\n        basis = f\"médiane de {m['n_sold']} ventes constatées en {m.get('days', '?')} j de suivi\"\n        if m.get(\"delay\") is not None:\n            basis += f\", revente en ~{m['delay']:.0f} j\"\n        lines = [\n            f\"💎 <b>Pépite Vinted</b> · {esc(d['cat'])}{' · neuf' if d['cond'] == 'neuf' else ''}\",\n            f\"<a href=\\\"{esc(d['url'])}\\\">{esc(d['title'][:90])}</a>\",\n            (f\"📉 Prix baissé : {eur(d['drop_from'])} → <b>{eur(d['price'])}</b>\" if d.get(\"drop_from\")\n             else f\"Prix : <b>{eur(d['price'])}</b>\") + f\" (coût réel {eur(ev['cost'])} avec frais et port)\",\n            f\"Revente visée : {eur(ev['resale'])} ({basis}, fourchette {eur(m['low'])}–{eur(m['high'])})\",\n            f\"<b>Profit ≈ {eur(ev['profit'])} · marge {ev['margin']:.0f} %</b> · confiance {ev['conf']:.0%}\",\n        ]\n        if ev[\"suspect\"]:\n            lines.append(\"⚠️ Prix très bas pour ce produit : vérifie les photos (boîte vide, copie, arnaque ?)\")\n        return \"\\n\".join(lines)\n\n    @staticmethod\n    def deal_buttons(d):\n        return {\"inline_keyboard\": [\n            [{\"text\": \"🛒 Ouvrir l'annonce\", \"url\": d[\"url\"]}],\n            [{\"text\": \"✅ Acheté\", \"callback_data\": f\"c:vinted:achete:{d['id']}\"},\n             {\"text\": \"👎 Faux positif\", \"callback_data\": f\"c:vinted:fp:{d['id']}\"}],\n        ]}\n\n    # ------------------------------------------------------------------ scan\n    def scan_query(self, q):\n        now = int(self.clock())\n        items = self.src.search(q[\"q\"], order=\"newest_first\", per_page=48, price_to=self.s[\"max_price\"])\n        seed = not q.get(\"seeded\")\n        for it in items:\n            self.stats[\"seen\"] += 1\n            old = self.store.get(it[\"id\"])\n            key = core.product_key(it[\"title\"])\n            cond = core.condition_group(it[\"status\"], it[\"title\"])\n            self.store.upsert(it, key, cond, \"scan\", now)\n            if key and self.s[\"auto_track\"] and old is None:\n                self.maybe_track(key, it[\"title\"])\n            if seed or not self.accept(it):\n                continue\n            if old is None:\n                if it[\"ts\"] and now - it[\"ts\"] > self.s[\"max_age_h\"] * 3600:\n                    continue  # vieille annonce remontée : elle a déjà été vue par tout le monde\n                self.analyse(it, q[\"q\"])\n            elif old[\"price\"] and it[\"price\"] <= old[\"price\"] * 0.95 - 0.5:\n                self.stats[\"drops\"] += 1\n                self.analyse(it, q[\"q\"], drop_from=old[\"price\"])\n        if seed:\n            q[\"seeded\"] = True\n            self.save_config()\n            self.log(f\"Recherche « {q['q']} » initialisée ({len(items)} annonces déjà en ligne, aucune alerte).\")\n\n    def check_sold(self, limit=6):\n        \"\"\"Suit les comparables disparus des recherches : c'est ce qui construit la base des VRAIS prix de vente.\"\"\"\n        now = int(self.clock())\n        rows = self.store.q(\n            \"\"\"SELECT id, price, state FROM listings WHERE state IN ('online', 'reserved') AND key IS NOT NULL\n               AND last_seen < ? AND last_check < ? AND first_seen > ?\n               ORDER BY (key IN (SELECT key FROM products)) DESC, last_check, last_seen LIMIT ?\"\"\",\n            (now - 6 * 3600, now - 12 * 3600, now - 45 * DAY, limit))\n        for r in rows:\n            st = self.src.item_state(r[\"id\"])\n            # « réservée puis disparue » : une vente quasi certaine ; disparue sans réservation : ambigu, on ne compte pas\n            if st == \"sold\" or (st == \"gone\" and r[\"state\"] == \"reserved\"):\n                self.store.x(\"UPDATE listings SET state = 'sold', sold_at = ?, sold_price = price, last_check = ? WHERE id = ?\",\n                             (now, now, r[\"id\"]))\n                self.stats[\"sold_found\"] += 1\n            elif st == \"unknown\":\n                self.store.x(\"UPDATE listings SET last_check = ? WHERE id = ?\", (now, r[\"id\"]))\n                self.stats[\"unknown_pages\"] = self.stats.get(\"unknown_pages\", 0) + 1\n            else:\n                self.store.x(\"UPDATE listings SET state = ?, last_check = ? WHERE id = ?\", (st, now, r[\"id\"]))\n\n    def due(self):\n        with self.lock:\n            return [q for q in self.queries if not q.get(\"paused\") and self.round % PRIO_EVERY.get(q[\"prio\"], 4) == 0]\n\n    def scan_round(self):\n        self.round += 1\n        for q in self.due():\n            if self.stop or not self.s[\"enabled\"]:\n                return\n            self.scan_query(q)\n        self.learn_step()\n        self.check_sold()\n        self.last_scan = self.clock()\n\n    def scan_loop(self):\n        while not self.stop:\n            if not self.s[\"enabled\"]:\n                self.wake.wait(10)\n                self.wake.clear()\n                continue\n            try:\n                self.scan_round()\n                if self.problem:\n                    self.log(\"Vinted répond de nouveau normalement.\", \"ok\")\n                self.problem, self.backoff = \"\", 0\n            except SourceError as e:\n                self.backoff = min(1800, max(60, self.backoff * 2))\n                first = not self.problem\n                if e.code == 404:\n                    self.problem = \"Vinted refuse l'API catalogue (404) : la méthode d'accès doit être adaptée.\"\n                elif e.code in (403, 429):\n                    self.problem = f\"Vinted bloque temporairement (HTTP {e.code}), pause de {self.backoff // 60} min.\"\n                else:\n                    self.problem = f\"Vinted injoignable ({e}), nouvel essai dans {self.backoff // 60} min.\"\n                self.log(self.problem, \"bad\" if first else \"info\")\n                self.wake.wait(self.backoff)\n                self.wake.clear()\n                continue\n            except Exception as e:  # une erreur imprévue ne doit jamais tuer le bot\n                self.log(f\"Erreur inattendue : {type(e).__name__}: {e}\", \"warn\")\n            self.wake.wait(random.uniform(8, 20))\n            self.wake.clear()\n\n    # ------------------------------------------------------------------ commandes\n    @staticmethod\n    def arg(args, *names):\n        for n in names:\n            v = str((args or {}).get(n, \"\") or \"\").strip()\n            if v:\n                return v\n        return \"\"\n\n    def deal_by_id(self, iid):\n        row = self.store.q(\"SELECT data FROM deals WHERE id = ?\", (iid,), one=True)\n        return json.loads(row[\"data\"]) if row else None\n\n    def handle(self, c):\n        cmd, args = c[\"cmd\"], c.get(\"args\") or {}\n        s = self.s\n        if cmd in (\"fp\", \"achete\"):\n            iid = self.arg(args, \"id\", \"text\").split()[0] if self.arg(args, \"id\", \"text\") else \"\"\n            d = self.deal_by_id(iid)\n            if not d:\n                return False, \"Annonce inconnue.\", False\n            self.store.x(\"UPDATE deals SET verdict = ? WHERE id = ?\", (cmd, iid))\n            self.store.x(\"INSERT INTO feedback (key, seller, kind, at) VALUES (?, ?, ?, ?)\", (d[\"key\"], d.get(\"seller\", \"\"), cmd, int(self.clock())))\n            if cmd == \"fp\":\n                return True, f\"👎 Noté. Après 2 faux positifs sur « {d['key']} », ce produit n'est plus signalé.\", False\n            return True, f\"✅ Achat noté : {d['title'][:60]} ({eur(d['price'])}).\", False\n        if cmd in (\"pepites\", \"deals\"):\n            return True, self.deals_text(), True\n        if cmd in (\"watch\", \"ajouter_recherche\"):\n            text = self.arg(args, \"q\", \"text\")\n            prio = self.arg(args, \"prio\") or \"moyenne\"\n            words = text.split()\n            if words and words[-1] in PRIO_EVERY:\n                prio, text = words[-1], \" \".join(words[:-1])\n            if len(text) < 2:\n                return False, \"Usage : /watch zelda switch [haute|moyenne|basse]\", False\n            if prio not in PRIO_EVERY:\n                prio = \"moyenne\"\n            with self.lock:\n                if any(q[\"q\"].lower() == text.lower() for q in self.queries):\n                    return False, f\"« {text} » est déjà surveillé.\", False\n                self.queries.append({\"q\": text, \"prio\": prio, \"seeded\": False, \"found\": 0})\n                self.save_config()\n            return True, f\"🔎 Recherche ajoutée : « {esc(text)} » (priorité {prio}).\", False\n        if cmd in (\"unwatch\", \"retirer\"):\n            n = self.arg(args, \"n\", \"text\")\n            with self.lock:\n                if not n.isdigit() or not 1 <= int(n) <= len(self.queries):\n                    return False, f\"Numéro de recherche invalide (1 à {len(self.queries)}).\", False\n                q = self.queries.pop(int(n) - 1)\n                self.save_config()\n            return True, f\"🗑 Recherche retirée : « {esc(q['q'])} ».\", False\n        if cmd == \"prio\":\n            words = self.arg(args, \"text\").split()\n            n = self.arg(args, \"n\") or (words[0] if words else \"\")\n            p = self.arg(args, \"prio\") or (words[1] if len(words) > 1 else \"\")\n            if not n.isdigit() or not 1 <= int(n) <= len(self.queries) or p not in PRIO_EVERY:\n                return False, \"Usage : prio <n°> haute|moyenne|basse\", False\n            self.queries[int(n) - 1][\"prio\"] = p\n            self.save_config()\n            return True, f\"Priorité de « {self.queries[int(n) - 1]['q']} » : {p}.\", False\n        if cmd == \"estimer\":\n            title = self.arg(args, \"titre\", \"text\")\n            key = core.product_key(title)\n            if not key:\n                return False, \"Produit non identifiable avec ce titre (ajoute le n° de set, le tome ou la console).\", False\n            cond = core.condition_group(\"\", title)\n            m = self.market(key, cond)\n            if not m:\n                return True, f\"🔎 {esc(key)} : pas assez de comparables pour donner un prix.\", True\n            return True, (f\"🔎 <b>{esc(key)}</b> ({cond})\\nPrix de revente : <b>{eur(m['price'])}</b> \"\n                          f\"({m['basis']}, {m['n_sold']} ventes, {m['n_active']} en ligne, {eur(m['low'])}–{eur(m['high'])})\"), True\n        if cmd == \"suivre\":\n            title = self.arg(args, \"titre\", \"text\")\n            key = core.product_key(title)\n            if not key:\n                return False, \"Produit non identifiable (ajoute le n° de set, le tome ou la console).\", False\n            self.track(key, title, \"manuel\")\n            self.store.x(\"UPDATE products SET origin = 'manuel' WHERE key = ?\", (key,))\n            return True, (f\"📂 Dossier ouvert : <b>{esc(key)}</b>. Je relève ses ventes ; alertes possibles après \"\n                          f\"{self.s['min_sold']:g} ventes constatées et {self.s['min_days']:g} jours de suivi.\"), True\n        if cmd == \"oublier\":\n            key = self.arg(args, \"key\", \"text\")\n            k2 = core.product_key(key) or key\n            row = self.store.q(\"SELECT key FROM products WHERE key = ?\", (k2,), one=True)\n            if not row:\n                return False, \"Dossier introuvable (donne la clé affichée dans le tableau, ex. lego:42083).\", False\n            self.store.x(\"DELETE FROM products WHERE key = ?\", (k2,))\n            return True, f\"🗑 Dossier fermé : {esc(k2)}.\", False\n        if cmd == \"produits\":\n            ds = self.dossiers(12)\n            if not ds:\n                return True, \"Aucun dossier pour l'instant.\", False\n            return True, \"📂 <b>Dossiers produits</b>\\n\" + \"\\n\".join(\n                f\"• {esc(d['label'][:40])} : {d['n_sold']} ventes\" + (f\", ~{eur(d['median'])}\" if d[\"median\"] else \"\")\n                + (\" ✅ prêt\" if d[\"ready\"] else f\" ({d['days']:.0f}/{self.s['min_days']:g} j)\") for d in ds), True\n        if cmd == \"scan\":\n            self.wake.set()\n            return True, \"🔍 Scan lancé.\", False\n        if cmd in (\"stop\", \"pause\"):\n            s[\"enabled\"] = False\n            self.save_config()\n            return True, \"⏹ Scans Vinted arrêtés.\", False\n        if cmd in (\"resume\", \"reprendre\"):\n            s[\"enabled\"] = True\n            self.save_config()\n            self.wake.set()\n            return True, \"▶ Scans Vinted repris.\", False\n        if cmd == \"set\":\n            k, v = self.arg(args, \"key\"), self.arg(args, \"value\")\n            if k in NUM_SETTINGS:\n                try:\n                    val = float(v.replace(\",\", \".\"))\n                except ValueError:\n                    return False, f\"Valeur invalide pour {k}\", False\n                if val < 0 or (k == \"gap\" and val < 1.5) or (k == \"conf_min\" and val > 1):\n                    return False, f\"Valeur hors limites pour {k}\", False\n                s[k] = val\n                if k == \"gap\":\n                    self.src.min_gap = val\n            elif k in (\"alerts\", \"auto_track\"):\n                s[k] = v in (\"1\", \"true\", \"oui\", \"Oui\")\n            else:\n                return False, f\"Réglage inconnu : {k}\", False\n            self.save_config()\n            return True, f\"Réglage {k} = {s[k]}\", False\n        if cmd == \"log\":\n            return True, \"📜 <b>Vinted</b>\\n<pre>\" + esc(\"\\n\".join(list(self.logbuf)[-12:]) or \"(vide)\") + \"</pre>\", True\n        return False, f\"Commande inconnue : {cmd}\", False\n\n    def run_command(self, c):\n        try:\n            ok, text, is_html = self.handle(c)\n        except SourceError as e:\n            ok, text, is_html = False, f\"Vinted indisponible : {e}\", False\n        except Exception as e:  # une commande ne doit jamais tuer l'agent\n            ok, text, is_html = False, f\"Erreur : {str(e)[:200]}\", False\n        self.hub.result(c[\"id\"], ok, text, html=is_html)\n\n    # ------------------------------------------------------------------ affichage\n    def recent_deals(self, days=7, limit=25):\n        rows = self.store.q(\"SELECT data, verdict FROM deals WHERE at > ? ORDER BY at DESC LIMIT ?\",\n                            (int(self.clock()) - days * DAY, limit))\n        return [{**json.loads(r[\"data\"]), \"verdict\": r[\"verdict\"]} for r in rows]\n\n    def dossiers(self, limit=40):\n        out = []\n        for p in self.store.q(\"SELECT key, label, origin FROM products\"):\n            best = max((self.dossier(p[\"key\"], c) for c in (\"occ\", \"neuf\")), key=lambda d: (d[\"ready\"], d[\"n_sold\"]))\n            out.append({**best, \"label\": p[\"label\"], \"origin\": p[\"origin\"]})\n        out.sort(key=lambda d: (d[\"ready\"], d[\"origin\"] == \"manuel\", d[\"n_sold\"]), reverse=True)\n        return out[:limit]\n\n    def deals_text(self):\n        ds = self.recent_deals(2, 8)\n        if not ds:\n            return \"Aucune pépite ces 2 derniers jours.\"\n        return \"💎 <b>Dernières pépites</b>\\n\" + \"\\n\".join(\n            f\"• <a href=\\\"{esc(d['url'])}\\\">{esc(d['title'][:50])}</a> {eur(d['price'])} → +{eur(d['ev']['profit'])}\" for d in ds)\n\n    def state(self):\n        s = self.s\n        st = self.store\n        now = int(self.clock())\n        n_listings = st.q(\"SELECT COUNT(*) n FROM listings\", one=True)[\"n\"]\n        n_sold = st.q(\"SELECT COUNT(*) n FROM listings WHERE state = 'sold'\", one=True)[\"n\"]\n        n_priced = st.q(\"SELECT COUNT(*) n FROM market WHERE data != '' AND at > ?\", (now - DAY,), one=True)[\"n\"]\n        n_deals = st.q(\"SELECT COUNT(*) n FROM deals WHERE at > ?\", (now - DAY,), one=True)[\"n\"]\n        n_bought = st.q(\"SELECT COUNT(*) n FROM deals WHERE verdict = 'achete'\", one=True)[\"n\"]\n        n_fp = st.q(\"SELECT COUNT(*) n FROM deals WHERE verdict = 'fp'\", one=True)[\"n\"]\n        dossiers = self.dossiers(400)\n        n_ready = sum(1 for d in dossiers if d[\"ready\"])\n        if self.problem:\n            status, summary = (\"bad\" if \"404\" in self.problem else \"warn\"), self.problem\n        elif not s[\"enabled\"]:\n            status, summary = \"idle\", \"Arrêté (bouton Reprendre pour relancer)\"\n        elif not self.last_scan:\n            status, summary = \"idle\", \"Premier tour en cours (les recherches sont initialisées sans alerte)\"\n        else:\n            status, summary = \"ok\", (f\"{n_deals} pépite(s) en 24 h · {n_ready}/{len(dossiers)} dossiers mûrs\"\n                                     if n_ready else f\"Apprentissage : {len(dossiers)} dossiers ouverts, aucun encore mûr \"\n                                     f\"({self.s['min_sold']:g} ventes + {self.s['min_days']:g} j requis)\")\n        deals = self.recent_deals()\n        return {\n            \"status\": status, \"summary\": summary,\n            \"metrics\": [\n                {\"label\": \"Pépites 24 h\", \"value\": str(n_deals)},\n                {\"label\": \"Dossiers mûrs / ouverts\", \"value\": f\"{n_ready} / {len(dossiers)}\"},\n                {\"label\": \"Achetées / faux positifs\", \"value\": f\"{n_bought} / {n_fp}\"},\n                {\"label\": \"Annonces suivies\", \"value\": str(n_listings)},\n                {\"label\": \"Ventes constatées\", \"value\": str(n_sold)},\n                {\"label\": \"Pages annonce illisibles\", \"value\": str(self.stats.get(\"unknown_pages\", 0))},\n                {\"label\": \"Produits chiffrés (24 h)\", \"value\": str(n_priced)},\n                {\"label\": \"Baisses de prix vues\", \"value\": str(self.stats[\"drops\"])},\n                {\"label\": \"Appels Vinted\", \"value\": str(self.src.calls)},\n                {\"label\": \"Source\", \"value\": self.src.last_status},\n                {\"label\": \"Dernier tour\", \"value\": f\"il y a {int(self.clock() - self.last_scan)} s\" if self.last_scan else \"—\"},\n            ],\n            \"tables\": [\n                {\"title\": \"Pépites (7 jours)\", \"columns\": [\"Annonce\", \"Prix\", \"Revente\", \"Profit\", \"Marge\", \"Avis\", \"Id\"], \"highlight\": 3,\n                 \"rows\": [[d[\"title\"][:70], eur(d[\"price\"]), eur(d[\"ev\"][\"resale\"]), eur(d[\"ev\"][\"profit\"]), f\"{d['ev']['margin']:.0f} %\",\n                           {\"achete\": \"✅ acheté\", \"fp\": \"👎 faux\"}.get(d[\"verdict\"], \"\"), d[\"id\"]] for d in deals],\n                 \"rowActions\": [{\"action\": \"achete\", \"label\": \"✅ Acheté\", \"args\": {\"id\": \"{6}\"}},\n                                {\"action\": \"fp\", \"label\": \"👎 Faux positif\", \"args\": {\"id\": \"{6}\"}}]},\n                {\"title\": \"Dossiers produits\", \"columns\": [\"Produit\", \"Clé\", \"Ventes\", \"Prix vendu\", \"Revente\", \"Suivi\", \"État\"],\n                 \"highlight\": 6,\n                 \"rows\": [[d[\"label\"][:50], d[\"key\"][:60], str(d[\"n_sold\"]), eur(d[\"median\"]) if d[\"median\"] else \"—\",\n                           f\"~{d['delay']:.0f} j\" if d[\"delay\"] is not None else \"—\", f\"{d['days']:.0f} j\",\n                           \"✅ prêt\" if d[\"ready\"] else \"📚 apprend\"] for d in dossiers[:40]],\n                 \"rowActions\": [{\"action\": \"oublier\", \"label\": \"Fermer\", \"args\": {\"key\": \"{1}\"}, \"danger\": True,\n                                 \"confirm\": \"Fermer le dossier « {0} » ?\"}]},\n                {\"title\": \"Recherches surveillées\", \"columns\": [\"N°\", \"Recherche\", \"Priorité\", \"Pépites\"],\n                 \"rows\": [[str(i + 1), q[\"q\"] + (\"\" if q.get(\"seeded\") else \" (initialisation)\"), q[\"prio\"], str(q.get(\"found\", 0))]\n                          for i, q in enumerate(self.queries)],\n                 \"rowActions\": [{\"action\": \"retirer\", \"label\": \"🗑 Retirer\", \"args\": {\"n\": \"{0}\"}, \"danger\": True,\n                                 \"confirm\": \"Ne plus surveiller « {1} » ?\"}]},\n            ],\n            \"actions\": [\n                {\"id\": \"pepites\", \"label\": \"💎 Dernières pépites\"},\n                {\"id\": \"scan\", \"label\": \"🔍 Scanner maintenant\"},\n                ({\"id\": \"stop\", \"label\": \"⏹ Arrêter les scans\", \"danger\": True, \"confirm\": \"Arrêter les scans Vinted ?\"} if s[\"enabled\"]\n                 else {\"id\": \"resume\", \"label\": \"▶ Reprendre les scans\"}),\n                {\"id\": \"watch\", \"label\": \"Ajouter une recherche\", \"args\": [{\"name\": \"q\", \"label\": \"Recherche\", \"placeholder\": \"zelda switch\"},\n                                                                           {\"name\": \"prio\", \"label\": \"Priorité\", \"placeholder\": \"haute / moyenne / basse\"}]},\n                {\"id\": \"suivre\", \"label\": \"Suivre un produit\", \"args\": [{\"name\": \"titre\", \"label\": \"Produit\", \"placeholder\": \"lego 42083 / berserk tome 1\"}]},\n                {\"id\": \"produits\", \"label\": \"📂 Dossiers produits\"},\n                {\"id\": \"oublier\", \"label\": \"Fermer\", \"hidden\": True, \"args\": [{\"name\": \"key\", \"label\": \"Clé\"}]},\n                {\"id\": \"estimer\", \"label\": \"Estimer un produit\", \"args\": [{\"name\": \"titre\", \"label\": \"Titre\", \"placeholder\": \"lego 10305 / naruto tome 12\"}]},\n                {\"id\": \"prio\", \"label\": \"Changer une priorité\", \"args\": [{\"name\": \"n\", \"label\": \"N°\"}, {\"name\": \"prio\", \"label\": \"haute / moyenne / basse\"}]},\n                {\"id\": \"log\", \"label\": \"📜 Journal\"},\n                {\"id\": \"retirer\", \"label\": \"Retirer\", \"hidden\": True, \"args\": [{\"name\": \"n\", \"label\": \"N°\"}]},\n                {\"id\": \"achete\", \"label\": \"Acheté\", \"hidden\": True, \"args\": [{\"name\": \"id\", \"label\": \"Id\"}]},\n                {\"id\": \"fp\", \"label\": \"Faux positif\", \"hidden\": True, \"args\": [{\"name\": \"id\", \"label\": \"Id\"}]},\n            ],\n            \"settings\": [\n                {\"key\": \"min_sold\", \"label\": \"Ventes constatées avant alerte\", \"type\": \"number\", \"value\": f\"{s['min_sold']:g}\",\n                 \"help\": \"Un produit n'est signalé qu'une fois ce nombre de ventes observé.\"},\n                {\"key\": \"min_days\", \"label\": \"Jours d'observation avant alerte\", \"type\": \"number\", \"value\": f\"{s['min_days']:g}\"},\n                {\"key\": \"max_sell_days\", \"label\": \"Délai de revente max (jours)\", \"type\": \"number\", \"value\": f\"{s['max_sell_days']:g}\"},\n                {\"key\": \"auto_track\", \"label\": \"Ouvrir un dossier pour chaque produit qui revient\", \"type\": \"bool\",\n                 \"value\": \"1\" if s[\"auto_track\"] else \"0\"},\n                {\"key\": \"profit_min\", \"label\": \"Profit minimum (€)\", \"type\": \"number\", \"value\": f\"{s['profit_min']:g}\"},\n                {\"key\": \"margin_min\", \"label\": \"Marge minimum (%)\", \"type\": \"number\", \"value\": f\"{s['margin_min']:g}\"},\n                {\"key\": \"conf_min\", \"label\": \"Confiance minimum (0 à 1)\", \"type\": \"number\", \"value\": f\"{s['conf_min']:g}\",\n                 \"help\": \"Monte-la si tu reçois trop d'alertes douteuses.\"},\n                {\"key\": \"discount\", \"label\": \"Décote de revente (%)\", \"type\": \"number\", \"value\": f\"{s['discount']:g}\",\n                 \"help\": \"Retirée au prix de revente : négociation et vente rapide.\"},\n                {\"key\": \"ship_in\", \"label\": \"Port à l'achat (€)\", \"type\": \"number\", \"value\": f\"{s['ship_in']:g}\"},\n                {\"key\": \"cheap_cap\", \"label\": \"Lego / Brio : prix max (€)\", \"type\": \"number\", \"value\": f\"{s['cheap_cap']:g}\"},\n                {\"key\": \"max_price\", \"label\": \"Prix max d'une annonce (€)\", \"type\": \"number\", \"value\": f\"{s['max_price']:g}\"},\n                {\"key\": \"gap\", \"label\": \"Écart entre appels Vinted (s)\", \"type\": \"number\", \"value\": f\"{s['gap']:g}\",\n                 \"help\": \"Minimum 1,5 s. Plus bas = plus rapide mais plus de blocages.\"},\n                {\"key\": \"alerts\", \"label\": \"Alertes Telegram\", \"type\": \"bool\", \"value\": \"1\" if s[\"alerts\"] else \"0\"},\n            ],\n            \"log\": list(self.logbuf)[-40:],\n            \"telegram\": [{\"cmd\": \"pepites\", \"text\": \"dernières pépites Vinted\"},\n                         {\"cmd\": \"suivre\", \"text\": \"ouvrir le dossier d'un produit\"},\n                         {\"cmd\": \"produits\", \"text\": \"dossiers produits Vinted\"},\n                         {\"cmd\": \"watch\", \"text\": \"surveiller une recherche Vinted\"},\n                         {\"cmd\": \"estimer\", \"text\": \"prix de revente d'un produit\"}],\n        }\n\n    # ------------------------------------------------------------------ boucle\n    def run(self):\n        threading.Thread(target=self.scan_loop, daemon=True).start()\n        self.hub.message(f\"🟢 <b>Vinted pépites</b> démarré en mode apprentissage · {len(self.queries)} recherches. \"\n                         f\"Un produit n'est signalé qu'après {self.s['min_sold']:g} ventes constatées et \"\n                         f\"{self.s['min_days']:g} jours de suivi. /produits pour voir les dossiers.\", html=True)\n        last_state = 0.0\n        while not self.stop:\n            if time.time() - last_state > STATE_EVERY:\n                self.hub.flush(self.state())\n                last_state = time.time()\n            for c in self.hub.poll(wait=15):\n                self.run_command(c)\n                self.hub.flush(self.state())\n                last_state = time.time()\n\n\ndef main():\n    cfg = load_config()\n    hub = Hub(\"vinted\", \"Vinted pépites\", cfg, log=lambda m: print(m, flush=True))\n    Bot(hub).run()\n\n\nif __name__ == \"__main__\":\n    main()\n"
};
export const INSTALL_TEMPLATE = "#!/usr/bin/env bash\n# Installe l'agent du hub sur ton serveur (OVH). Lancé par : curl -fsSL -H \"Authorization: Bearer CLE\" URL/agent/install.sh | bash\n# Idempotent : tu peux le relancer pour mettre à jour. Rien n'est supprimé, les anciens fichiers sont sauvegardés.\nset -euo pipefail\n\nHUB_URL=\"__HUB_URL__\"\nHUB_KEY=\"__HUB_KEY__\"\nDIR=\"${BOT_HUB_DIR:-$HOME/bot-hub}\"\nSYSTEMCTL=\"${SYSTEMCTL:-sudo systemctl}\"\nUNIT_DIR=\"${UNIT_DIR:-/etc/systemd/system}\"\nSUDO=\"${SUDO_CMD-sudo}\"\n\nsay() { printf '\\n== %s\\n' \"$*\"; }\nok()  { printf '   ✓ %s\\n' \"$*\"; }\nwarn(){ printf '   ! %s\\n' \"$*\"; }\n\nsay \"Dossier $DIR\"\nmkdir -p \"$DIR\"\ncd \"$DIR\"\n\n# --- fichiers de l'agent (intégrés à ce script) -----------------------------------------------\n__FILES__\n\ncommand -v python3 >/dev/null || { echo \"python3 est requis.\"; exit 1; }\n# hub.json : adresse + clé mises à jour, le reste (proxy TGTG...) est conservé\nHUB_URL=\"$HUB_URL\" HUB_KEY=\"$HUB_KEY\" python3 - <<'PYEOF'\nimport json, os\ntry:\n    cfg = json.load(open(\"hub.json\", encoding=\"utf8\"))\n    if not isinstance(cfg, dict): cfg = {}\nexcept Exception:\n    cfg = {}\ncfg.update(url=os.environ[\"HUB_URL\"], key=os.environ[\"HUB_KEY\"])\njson.dump(cfg, open(\"hub.json\", \"w\", encoding=\"utf8\"), indent=2)\nPYEOF\nchmod 600 hub.json\nok \"Fichiers de l'agent écrits\"\n\ncommand -v python3 >/dev/null || { echo \"python3 est requis.\"; exit 1; }\nPY=\"$(command -v python3)\"\n\n# --- TGTG : on reprend les jetons et le proxy de l'ancien script -------------------------------\nsay \"Too Good To Go\"\nOLD_UNIT=\"\"\nif $SYSTEMCTL cat tgtg >/dev/null 2>&1; then OLD_UNIT=\"tgtg\"; fi\nOLD_SCRIPT=\"\"\nfor c in \"$HOME/tgtg_monitor.py\" \"$HOME/tgtgAl/tgtg_monitor.py\" \"$HOME/tgtg/tgtg_monitor.py\"; do\n  [ -f \"$c\" ] && OLD_SCRIPT=\"$c\" && break\ndone\nif [ -z \"$OLD_SCRIPT\" ] && [ -n \"$OLD_UNIT\" ]; then\n  OLD_SCRIPT=\"$($SYSTEMCTL cat tgtg 2>/dev/null | grep -Eo '/[^ ]*tgtg_monitor\\.py' | head -1 || true)\"\nfi\nif [ -n \"$OLD_UNIT\" ]; then\n  UPY=\"$($SYSTEMCTL cat tgtg 2>/dev/null | sed -n 's/^ExecStart=\\([^ ]*python[^ ]*\\).*/\\1/p' | head -1 || true)\"\n  [ -n \"$UPY\" ] && [ -x \"$UPY\" ] && PY=\"$UPY\"\nfi\nOLD_DIR=\"\"; [ -n \"$OLD_SCRIPT\" ] && OLD_DIR=\"$(dirname \"$OLD_SCRIPT\")\"\n\nif [ -n \"$OLD_DIR\" ] && [ -f \"$OLD_DIR/tgtg_tokens.json\" ] && [ ! -f tgtg_tokens.json ]; then\n  cp \"$OLD_DIR/tgtg_tokens.json\" tgtg_tokens.json; chmod 600 tgtg_tokens.json; ok \"Jetons TGTG repris de $OLD_DIR\"\nfi\nif [ -n \"$OLD_DIR\" ] && [ -f \"$OLD_DIR/tgtg_config.json\" ] && [ ! -f tgtg_config.json ]; then\n  cp \"$OLD_DIR/tgtg_config.json\" tgtg_config.json; ok \"Réglages (horaires, intervalle, auto) repris\"\nfi\n\nif [ -f tgtg_tokens.json ]; then\n  # proxy Webshare lu dans l'ancien script (le jeton Telegram n'est PAS recopié)\n  if [ -n \"$OLD_SCRIPT\" ] && [ -f \"$OLD_SCRIPT\" ]; then\n    \"$PY\" - \"$OLD_SCRIPT\" <<'PYEOF'\nimport json, re, sys\nsrc = open(sys.argv[1], encoding=\"utf8\").read()\ndef get(name, default=None):\n    m = re.search(r'^%s\\s*=\\s*[\"\\']?([^\"\\'\\n#]+?)[\"\\']?\\s*(?:#.*)?$' % name, src, re.M)\n    return m.group(1).strip() if m else default\ncfg = json.load(open(\"hub.json\"))\nif get(\"PROXY_PASS\"):\n    cfg[\"tgtg\"] = {\"proxy\": {\"host\": get(\"PROXY_BASE\", \"p.webshare.io\"), \"port\": int(get(\"PROXY_PORT\", \"80\")),\n                             \"user_base\": get(\"PROXY_USER_BASE\", \"\"), \"password\": get(\"PROXY_PASS\"), \"count\": int(get(\"PROXY_COUNT\", \"1\"))}}\n    json.dump(cfg, open(\"hub.json\", \"w\"), indent=2)\n    print(\"   ✓ Proxy Webshare repris de l'ancien script\")\nPYEOF\n  else\n    warn \"Ancien script introuvable : TGTG tournera sans proxy (ajoute \\\"tgtg\\\": {\\\"proxy\\\": ...} dans hub.json sinon).\"\n  fi\n  if ! \"$PY\" -c \"import tgtg_scanner\" 2>/dev/null; then\n    say \"Installation de la bibliothèque TGTG\"\n    \"$PY\" -m pip install --user --break-system-packages \"git+https://github.com/Der-Henning/tgtg.git\" requests >/dev/null 2>&1 \\\n      || \"$PY\" -m pip install --user \"git+https://github.com/Der-Henning/tgtg.git\" requests\n  fi\n  # on coupe l'ancien bot (sinon deux scripts se disputent le même Telegram)\n  if [ -n \"$OLD_UNIT\" ]; then $SYSTEMCTL disable --now tgtg >/dev/null 2>&1 && ok \"Ancien service « tgtg » arrêté et désactivé (il n'est pas supprimé)\"; fi\n  pkill -f tgtg_monitor.py 2>/dev/null && ok \"Ancien processus arrêté\" || true\n  if crontab -l 2>/dev/null | grep -q tgtg_monitor; then\n    crontab -l > \"crontab.avant-hub.txt\" 2>/dev/null || true\n    crontab -l 2>/dev/null | grep -v tgtg_monitor | crontab - && ok \"Ancien relanceur cron retiré (sauvegarde : $DIR/crontab.avant-hub.txt)\"\n  fi\n  TGTG=1\nelse\n  warn \"Aucun jeton TGTG trouvé : TGTG n'est pas branché (copie tgtg_tokens.json dans $DIR puis relance).\"\n  TGTG=0\nfi\n\n# --- scripts à surveiller (ali-coins...) ----------------------------------------------------\nsay \"Autres bots\"\nif [ ! -f scripts.json ]; then\n  \"$PY\" - <<'PYEOF'\nimport json, os\nspecs = []\nhome = os.path.expanduser(\"~\")\nali = os.path.join(home, \"ali-coins\")\nif os.path.isfile(os.path.join(ali, \"run_all.sh\")):\n    specs.append({\"id\": \"alicoins\", \"name\": \"AliExpress coins\", \"cwd\": ali, \"run\": \"./run_all.sh --no-delay\", \"log\": \"cron.log\",\n                  \"dry_args\": \"--dry-run --notify\", \"stale_hours\": 36, \"daily_at\": \"09:30\",\n                  \"metrics\": [{\"label\": \"Pièces gagnées\", \"regex\": r\"coins[=: ]+(\\d+)\"},\n                              {\"label\": \"Série (jours)\", \"regex\": r\"streak[=: ]+(\\d+)\"},\n                              {\"label\": \"Solde\", \"regex\": r\"balance[=: ]+(\\d+)\"}]})\njson.dump(specs, open(\"scripts.json\", \"w\"), indent=2, ensure_ascii=False)\nprint(\"   ✓ AliExpress coins détecté\" if specs else \"   ! ali-coins non trouvé dans ~/ali-coins (scripts.json vide : ajoute-le à la main plus tard)\")\nPYEOF\nfi\n\"$PY\" - <<'PYEOF'\n# scripts.json déjà présent : ajoute le passage quotidien automatique s'il manque (ali-coins sans cron)\nimport json\nspecs = json.load(open(\"scripts.json\"))\nch = False\nfor sp in specs:\n    if sp.get(\"id\") == \"alicoins\" and \"daily_at\" not in sp:\n        sp[\"daily_at\"] = \"09:30\"; ch = True\nif ch:\n    json.dump(specs, open(\"scripts.json\", \"w\"), indent=2, ensure_ascii=False)\n    print(\"   ✓ AliExpress coins : passage quotidien automatique à 09h30 (modifiable dans scripts.json)\")\nPYEOF\nSCRIPTS=0\n\"$PY\" -c \"import json,sys; sys.exit(0 if json.load(open('scripts.json')) else 1)\" 2>/dev/null && SCRIPTS=1\n\n# --- services systemd ---------------------------------------------------------------------------\nsay \"Services\"\nunit() { # nom, description, commande\n  $SUDO tee \"$UNIT_DIR/$1.service\" >/dev/null <<UNIT\n[Unit]\nDescription=$2\nAfter=network-online.target\nWants=network-online.target\n\n[Service]\nUser=$(id -un)\nWorkingDirectory=$DIR\nExecStart=$3\nRestart=always\nRestartSec=5\n\n[Install]\nWantedBy=multi-user.target\nUNIT\n}\nif [ \"$TGTG\" = 1 ]; then unit hub-tgtg \"Bot hub - Too Good To Go\" \"$PY $DIR/tgtg_hub.py\"; fi\nunit hub-medinlyon \"Bot hub - MédinLyon\" \"$PY $DIR/medinlyon.py\"\nsay \"Vinted pépites\"\nif ! \"$PY\" -c \"import curl_cffi\" 2>/dev/null; then\n  \"$PY\" -m pip install --user --break-system-packages curl_cffi >/dev/null 2>&1 || \"$PY\" -m pip install --user curl_cffi\nfi\n\"$PY\" -c \"import curl_cffi\" 2>/dev/null && ok \"curl_cffi présent (empreinte navigateur pour Vinted)\" || warn \"curl_cffi non installé : Vinted refusera les appels\"\nunit hub-vinted \"Bot hub - Vinted pépites\" \"$PY $DIR/vinted_hub.py\"\nif [ \"$SCRIPTS\" = 1 ]; then unit hub-scripts \"Bot hub - scripts (ali-coins...)\" \"$PY $DIR/script_agent.py\"; fi\n$SYSTEMCTL daemon-reload\n[ \"$TGTG\" = 1 ] && $SYSTEMCTL enable hub-tgtg >/dev/null 2>&1 && $SYSTEMCTL restart hub-tgtg && ok \"hub-tgtg démarré\"\n$SYSTEMCTL enable hub-medinlyon >/dev/null 2>&1 && $SYSTEMCTL restart hub-medinlyon && ok \"hub-medinlyon démarré\"\n$SYSTEMCTL enable hub-vinted >/dev/null 2>&1 && $SYSTEMCTL restart hub-vinted && ok \"hub-vinted démarré\"\n[ \"$SCRIPTS\" = 1 ] && $SYSTEMCTL enable hub-scripts >/dev/null 2>&1 && $SYSTEMCTL restart hub-scripts && ok \"hub-scripts démarré\"\n\n# --- vérification --------------------------------------------------------------------------------\nsay \"Vérification\"\nsleep 4\nif curl -fsS -m 20 -H \"Authorization: Bearer $HUB_KEY\" \"$HUB_URL/api/agent/poll?bot=ping&wait=0\" >/dev/null; then\n  ok \"Le serveur joint bien le hub\"\nelse\n  warn \"Le serveur ne joint pas le hub ($HUB_URL). Vérifie sa connexion internet.\"\nfi\necho\necho \"Terminé. Dans Telegram, envoie /menu : tes bots doivent apparaître dans la minute.\"\necho \"Journaux : journalctl -u hub-tgtg -f   (ou hub-scripts, hub-vinted)\"\n";
